// Life Sciences quizzes — bb101 through bb140
export const LIFE_SCIENCES_2_QUIZZES = [
  {
    id:'bb101', cat:'Life Sciences', title:'Taxonomy & Classification Systems', diff:'Easy',
    qs:[
      { q:`What is the correct order of taxonomic ranks from broadest to most specific?`, ch:[`Domain, Kingdom, Phylum, Class, Order, Family, Genus, Species`,`Species, Genus, Family, Order, Class, Phylum, Kingdom, Domain`,`Kingdom, Domain, Phylum, Class, Family, Order, Genus, Species`,`Domain, Phylum, Kingdom, Order, Class, Family, Species, Genus`], ans:0, exp:`The standard hierarchy from broadest to narrowest is Domain, Kingdom, Phylum, Class, Order, Family, Genus, Species. A common mnemonic is "Dear King Philip Came Over For Good Soup."` },
      { q:`Who is credited with developing binomial nomenclature?`, ch:[`Gregor Mendel`,`Carl Linnaeus`,`Louis Pasteur`,`Charles Darwin`], ans:1, exp:`Carl Linnaeus developed the two-name (genus + species) system in the 18th century, standardizing scientific naming of organisms.` },
      { q:`In the scientific name Homo sapiens, "Homo" represents the:`, ch:[`Order`,`Species`,`Genus`,`Family`], ans:2, exp:`In binomial nomenclature the first word is the genus (capitalized) and the second is the species epithet (lowercase); "sapiens" is the species.` },
      { q:`The three-domain system divides life into which groups?`, ch:[`Prokaryotes, Eukaryotes, Viruses`,`Monera, Protista, Animalia`,`Plants, Animals, Fungi`,`Bacteria, Archaea, Eukarya`], ans:3, exp:`Carl Woese proposed the three-domain system: Bacteria, Archaea, and Eukarya, based on differences in ribosomal RNA sequences.` },
      { q:`Which of these is NOT one of the traditional five kingdoms?`, ch:[`Archaea`,`Fungi`,`Monera`,`Protista`], ans:0, exp:`The traditional five-kingdom system (Monera, Protista, Fungi, Plantae, Animalia) predates the recognition of Archaea as a separate domain from Bacteria.` },
      { q:`Two organisms belonging to the same genus but different species can:`, ch:[`Interbreed to produce fertile offspring under any conditions`,`Share many similar traits but generally cannot produce fertile offspring together`,`Only exist in the same kingdom`,`Never share any traits`], ans:1, exp:`Species within the same genus are closely related and share many characteristics, but the biological species concept holds that different species typically cannot interbreed to produce fertile offspring.` },
      { q:`Which characteristic is used to classify organisms into Kingdom Fungi rather than Kingdom Plantae?`, ch:[`Fungi have no nucleus`,`Fungi are photosynthetic like plants`,`Fungi cell walls contain chitin rather than cellulose, and fungi are heterotrophic`,`Fungi lack cell walls entirely`], ans:2, exp:`Fungal cell walls are made of chitin (not cellulose as in plants), and fungi absorb nutrients as heterotrophs rather than photosynthesizing.` },
      { q:`A dichotomous key is a tool used to:`, ch:[`Measure the age of a fossil`,`Determine an organism's chromosome number`,`Sequence an organism's DNA`,`Identify organisms through a series of paired, contrasting choices`], ans:3, exp:`A dichotomous key presents a series of two-choice statements about characteristics, guiding the user step by step to the identification of an organism.` },
      { q:`Which domain includes organisms that often live in extreme environments such as hot springs and salt lakes?`, ch:[`Archaea`,`Protista`,`Eukarya`,`Bacteria`], ans:0, exp:`Archaea include many extremophiles adapted to extreme heat, salinity, or acidity, though some archaea also live in moderate environments.` },
      { q:`Viruses are generally excluded from the three-domain classification system because:`, ch:[`They are too large to classify`,`They are not considered to be living organisms in the traditional cellular sense`,`They only infect plants`,`They lack genetic material`], ans:1, exp:`Viruses lack independent metabolism and cannot reproduce without a host cell, so they are typically classified outside the three-domain system of cellular life.` },
      { q:`Which pair of organisms would most likely share the most recent common ancestor?`, ch:[`Two organisms in the same domain only`,`Two organisms in different kingdoms`,`Two organisms in the same species`,`Two organisms in the same kingdom only`], ans:2, exp:`Taxonomic rank reflects evolutionary relatedness; organisms in the same species share the most recent common ancestor compared to broader shared ranks.` },
      { q:`Phylogenetic trees are primarily used to depict:`, ch:[`The number of offspring a species produces`,`Climate patterns affecting ecosystems`,`The geographic range of a species`,`Evolutionary relationships among organisms`], ans:3, exp:`Phylogenetic trees are branching diagrams that show hypothesized evolutionary relationships and common ancestry among groups of organisms.` },
      { q:`Which of the following is an example of correctly formatted binomial nomenclature?`, ch:[`Panthera leo`,`PANTHERA LEO`,`Panthera Leo`,`panthera leo`], ans:0, exp:`Proper binomial nomenclature capitalizes the genus and keeps the species epithet lowercase, with both names italicized or underlined: Panthera leo.` },
      { q:`Cladistics classifies organisms primarily based on:`, ch:[`Physical size`,`Shared derived characteristics inherited from a common ancestor`,`Habitat location`,`Number of offspring produced`], ans:1, exp:`Cladistics groups organisms into clades based on shared derived traits (synapomorphies) that indicate common ancestry, rather than overall similarity.` },
    ]
  },
  {
    id:'bb102', cat:'Life Sciences', title:'Plant Biology & Photosynthesis Structures', diff:'Easy',
    qs:[
      { q:`Which plant organelle is the primary site of photosynthesis?`, ch:[`Golgi apparatus`,`Mitochondrion`,`Chloroplast`,`Nucleus`], ans:2, exp:`Chloroplasts contain chlorophyll and the machinery needed to capture light energy and convert it into chemical energy during photosynthesis.` },
      { q:`Stomata are small openings on leaves that primarily function to:`, ch:[`Produce chlorophyll`,`Store excess sugar`,`Anchor the plant in soil`,`Allow gas exchange (CO2 in, O2 and water vapor out)`], ans:3, exp:`Stomata, typically on the underside of leaves, open and close to regulate the exchange of carbon dioxide, oxygen, and water vapor with the atmosphere.` },
      { q:`Guard cells regulate stomatal opening and closing primarily by changes in:`, ch:[`Turgor pressure due to water movement in and out of the cells`,`Cell wall thickness`,`Chromosome number`,`Chlorophyll concentration`], ans:0, exp:`When guard cells take up water and become turgid, they bow outward and open the stomatal pore; loss of turgor causes the pore to close.` },
      { q:`The green pigment chlorophyll primarily absorbs which wavelengths of light most strongly?`, ch:[`Green light`,`Red and blue light`,`Yellow light only`,`Infrared light`], ans:1, exp:`Chlorophyll strongly absorbs red and blue wavelengths and reflects green light, which is why most chlorophyll-containing plant tissue appears green.` },
      { q:`In photosynthesis, the light-dependent reactions take place in the:`, ch:[`Cytoplasm`,`Stroma`,`Thylakoid membrane`,`Mitochondrial matrix`], ans:2, exp:`The light-dependent reactions occur in the thylakoid membranes, where light energy is captured and used to produce ATP and NADPH.` },
      { q:`The Calvin cycle (light-independent reactions) occurs in the:`, ch:[`Nucleus`,`Cell wall`,`Thylakoid lumen`,`Stroma of the chloroplast`], ans:3, exp:`The Calvin cycle takes place in the stroma, the fluid-filled space surrounding the thylakoids, where CO2 is fixed into sugars using ATP and NADPH.` },
      { q:`What are the overall reactants of photosynthesis?`, ch:[`Carbon dioxide and water`,`ATP and NADPH only`,`Nitrogen and water`,`Glucose and oxygen`], ans:0, exp:`Photosynthesis uses carbon dioxide and water, along with light energy, to produce glucose and oxygen: 6CO2 + 6H2O + light → C6H12O6 + 6O2.` },
      { q:`Root hairs increase a plant's ability to:`, ch:[`Photosynthesize more efficiently`,`Absorb water and minerals from soil`,`Produce seeds`,`Store starch`], ans:1, exp:`Root hairs are thin extensions of root epidermal cells that greatly increase surface area for absorbing water and dissolved minerals from soil.` },
      { q:`Xylem tissue in plants is primarily responsible for:`, ch:[`Gas exchange`,`Transporting sugars from leaves to roots`,`Transporting water and dissolved minerals upward from roots to leaves`,`Photosynthesis`], ans:2, exp:`Xylem is vascular tissue composed of dead, hollow cells that transport water and minerals from roots up to stems and leaves, driven largely by transpiration.` },
      { q:`Phloem tissue primarily transports:`, ch:[`Carbon dioxide`,`Water only`,`Oxygen`,`Sugars (products of photosynthesis) throughout the plant`], ans:3, exp:`Phloem transports sugars (mainly sucrose) produced by photosynthesis from source tissues (like leaves) to sink tissues (like roots and growing parts).` },
      { q:`Transpiration refers to the:`, ch:[`Loss of water vapor from plant leaves, mainly through stomata`,`Absorption of sunlight by chlorophyll`,`Growth of new root tissue`,`Process of seed dispersal`], ans:0, exp:`Transpiration is the evaporation of water from plant surfaces, primarily through open stomata, which helps drive water movement up through the xylem.` },
      { q:`Which structure in a leaf contains the most chloroplasts and is the main site of photosynthesis?`, ch:[`Epidermis`,`Mesophyll cells`,`Cuticle`,`Vascular bundle`], ans:1, exp:`Mesophyll cells, particularly the palisade mesophyll layer, are packed with chloroplasts and are the primary photosynthetic tissue in a leaf.` },
      { q:`The waxy cuticle on leaf surfaces primarily functions to:`, ch:[`Store excess glucose`,`Absorb extra sunlight`,`Reduce water loss from the leaf surface`,`Increase gas exchange`], ans:2, exp:`The cuticle is a waxy, waterproof layer that helps prevent excessive evaporation of water from the leaf's outer surface.` },
      { q:`What by-product of photosynthesis is released into the atmosphere and used by animals for respiration?`, ch:[`Water vapor only`,`Carbon dioxide`,`Nitrogen`,`Oxygen`], ans:3, exp:`Photosynthesis splits water molecules and releases oxygen gas as a by-product, which is then used by aerobic organisms during cellular respiration.` },
    ]
  },
  {
    id:'bb103', cat:'Life Sciences', title:'Plant Reproduction & Life Cycles', diff:'Medium',
    qs:[
      { q:`In flowering plants, the male reproductive structure that produces pollen is the:`, ch:[`Stamen`,`Sepal`,`Ovary`,`Pistil`], ans:0, exp:`The stamen, composed of the filament and anther, is the male part of the flower; the anther produces pollen grains containing sperm cells.` },
      { q:`The female reproductive structure of a flower, which includes the stigma, style, and ovary, is called the:`, ch:[`Petal`,`Pistil (carpel)`,`Anther`,`Stamen`], ans:1, exp:`The pistil (or carpel) is the female reproductive part of a flower, consisting of the stigma (receives pollen), style, and ovary (contains ovules).` },
      { q:`Double fertilization in flowering plants results in the formation of:`, ch:[`A pollen tube only`,`Two identical embryos`,`A zygote and a triploid endosperm`,`Two separate seeds from one ovule`], ans:2, exp:`In double fertilization, one sperm fertilizes the egg to form a diploid zygote, while a second sperm fuses with two polar nuclei to form triploid endosperm, which nourishes the developing embryo.` },
      { q:`Pollination is best defined as:`, ch:[`The germination of a seed`,`The dispersal of fruit`,`The fusion of sperm and egg nuclei`,`The transfer of pollen from anther to stigma`], ans:3, exp:`Pollination is the transfer of pollen grains from the anther (male) to the stigma (female), which is a prerequisite step before fertilization can occur.` },
      { q:`Which of these is an example of an abiotic pollination method?`, ch:[`Wind carrying pollen between plants`,`Bats transferring pollen`,`Bees carrying pollen`,`Birds transferring pollen while feeding`], ans:0, exp:`Wind pollination (anemophily) is abiotic, not requiring an animal vector; grasses and many trees rely on wind to disperse lightweight pollen.` },
      { q:`A seed is best described as:`, ch:[`A mature ovary`,`A mature ovule containing an embryo and stored food`,`An unfertilized egg cell`,`A pollen grain`], ans:1, exp:`A seed develops from a fertilized ovule and contains an embryonic plant along with stored nutrients (endosperm or cotyledons) and a protective seed coat.` },
      { q:`A fruit, in the botanical sense, develops from the:`, ch:[`Petals`,`Sepals`,`Ovary of the flower`,`Filament`], ans:2, exp:`After fertilization, the ovary wall matures and develops into the fruit, which surrounds and protects the seed(s).` },
      { q:`Alternation of generations in plants refers to the life cycle alternating between:`, ch:[`Seed and fruit stages only`,`Root and shoot growth phases`,`Male and female organisms`,`A multicellular diploid sporophyte stage and a multicellular haploid gametophyte stage`], ans:3, exp:`Plant life cycles alternate between a diploid sporophyte generation (produces spores by meiosis) and a haploid gametophyte generation (produces gametes by mitosis).` },
      { q:`In seedless vascular plants like ferns, the dominant, visible generation is the:`, ch:[`Sporophyte`,`Zygote only`,`Seed`,`Gametophyte`], ans:0, exp:`In ferns, the large leafy plant we typically see is the diploid sporophyte; the small, separate gametophyte is a tiny, often heart-shaped structure.` },
      { q:`In mosses (bryophytes), which generation is dominant?`, ch:[`Sporophyte`,`Gametophyte`,`Neither is dominant`,`Zygote`], ans:1, exp:`Unlike most vascular plants, mosses have a dominant gametophyte generation; the sporophyte remains small and physically attached to and dependent on the gametophyte.` },
      { q:`Vegetative propagation (asexual reproduction) in plants can occur through structures such as:`, ch:[`Seeds only`,`Pollen grains`,`Runners, tubers, or bulbs`,`Spores exclusively`], ans:2, exp:`Many plants reproduce asexually via vegetative structures like runners (strawberries), tubers (potatoes), or bulbs (onions), producing genetically identical offspring.` },
      { q:`Seed dormancy is an adaptation that primarily helps a seed:`, ch:[`Prevent pollination`,`Increase pollen production`,`Germinate immediately regardless of conditions`,`Delay germination until environmental conditions are favorable`], ans:3, exp:`Dormancy allows a seed to survive unfavorable conditions (cold, drought) and germinate only when factors like moisture, temperature, and light become favorable.` },
      { q:`Which structure in a seed provides the initial stored food source for the germinating embryo in many flowering plants?`, ch:[`Endosperm or cotyledons`,`Sepal`,`Stigma`,`Petal`], ans:0, exp:`Endosperm (from double fertilization) or cotyledons store carbohydrates, proteins, and lipids that nourish the embryo during germination before true leaves can photosynthesize.` },
      { q:`Gymnosperms differ from angiosperms in that gymnosperms:`, ch:[`Produce flowers and enclosed seeds`,`Produce "naked" seeds not enclosed in an ovary/fruit, often on cones`,`Do not produce seeds at all`,`Reproduce only asexually`], ans:1, exp:`Gymnosperms (like conifers) produce seeds that are not enclosed within an ovary or fruit; seeds often develop exposed on the surface of cone scales.` },
    ]
  },
  {
    id:'bb104', cat:'Life Sciences', title:'Human Skeletal System', diff:'Easy',
    qs:[
      { q:`Approximately how many bones are in the adult human skeleton?`, ch:[`156`,`106`,`206`,`306`], ans:2, exp:`The adult human skeleton typically has 206 bones, though infants are born with more (~270) that fuse together during growth.` },
      { q:`The skeletal system is divided into which two main divisions?`, ch:[`Cranial and spinal skeleton`,`Long and short bone systems`,`Upper and lower skeleton`,`Axial and appendicular skeleton`], ans:3, exp:`The axial skeleton includes the skull, vertebral column, and rib cage; the appendicular skeleton includes the limbs and the girdles that attach them.` },
      { q:`Which type of joint allows the greatest range of motion, such as at the shoulder and hip?`, ch:[`Ball-and-socket joint`,`Pivot joint`,`Fixed (fibrous) joint`,`Hinge joint`], ans:0, exp:`Ball-and-socket joints, found at the shoulder and hip, allow movement in multiple directions including rotation, giving them the widest range of motion.` },
      { q:`The knee and elbow are examples of which type of joint?`, ch:[`Pivot`,`Hinge`,`Saddle`,`Ball-and-socket`], ans:1, exp:`Hinge joints, like the knee and elbow, allow movement primarily in one plane (flexion and extension), similar to a door hinge.` },
      { q:`Which connective tissue attaches bone to bone at a joint?`, ch:[`Fascia`,`Tendon`,`Ligament`,`Cartilage`], ans:2, exp:`Ligaments are fibrous connective tissue bands that connect bone to bone, stabilizing joints. Tendons, in contrast, connect muscle to bone.` },
      { q:`Which of the following is a primary function of the skeletal system?`, ch:[`Regulating heart rate`,`Digesting food`,`Producing hormones exclusively`,`Providing structural support and protecting internal organs`], ans:3, exp:`The skeleton provides a rigid framework for support, protects vital organs (e.g., the skull protects the brain, the ribcage protects the heart and lungs), and enables movement via muscle attachment.` },
      { q:`Red blood cells are primarily produced in the:`, ch:[`Red bone marrow`,`Cartilage`,`Periosteum`,`Yellow bone marrow`], ans:0, exp:`Red bone marrow, found in flat bones like the pelvis, sternum, and vertebrae in adults, is the site of hematopoiesis (blood cell production).` },
      { q:`The outer membrane covering the surface of bones, important for bone growth and repair, is called the:`, ch:[`Diaphysis`,`Periosteum`,`Endosteum`,`Epiphysis`], ans:1, exp:`The periosteum is a tough connective tissue membrane covering the outer surface of bones (except at joint surfaces), containing blood vessels and cells important for bone growth and repair.` },
      { q:`Which bone is NOT part of the axial skeleton?`, ch:[`Skull`,`Vertebrae`,`Femur`,`Ribs`], ans:2, exp:`The femur is a limb bone and belongs to the appendicular skeleton. Skull, vertebrae, and ribs are all part of the axial skeleton.` },
      { q:`Cartilage differs from bone in that cartilage is:`, ch:[`Found only in the skull`,`Composed mainly of calcium crystals`,`Harder and more mineralized than bone`,`Softer, more flexible connective tissue lacking blood vessels`], ans:3, exp:`Cartilage is a flexible connective tissue without blood vessels (avascular), found at joints, in the ear, nose, and other locations, providing cushioning and flexible support.` },
      { q:`The shaft (long, tubular central portion) of a long bone is called the:`, ch:[`Diaphysis`,`Periosteum`,`Medullary cavity only`,`Epiphysis`], ans:0, exp:`The diaphysis is the long, cylindrical shaft of a long bone, while the epiphyses are the rounded ends near the joints.` },
      { q:`Which of the following best describes the function of the vertebral column?`, ch:[`It has no protective function`,`It protects the spinal cord and supports the body's weight`,`It solely produces hormones`,`It functions only in digestion`], ans:1, exp:`The vertebral column (spine) encases and protects the spinal cord while providing structural support for the trunk and enabling flexible movement.` },
      { q:`Osteoporosis is a condition characterized by:`, ch:[`Fusion of joints`,`Excessive bone density`,`Loss of bone density, making bones more fragile and prone to fracture`,`Overproduction of cartilage`], ans:2, exp:`Osteoporosis results from an imbalance between bone resorption and formation, leading to decreased bone mineral density and increased fracture risk, common in aging populations.` },
    ]
  },
  {
    id:'bb105', cat:'Life Sciences', title:'Human Muscular System', diff:'Easy',
    qs:[
      { q:`Which type of muscle tissue is voluntary and attached to bones?`, ch:[`Involuntary muscle only`,`Smooth muscle`,`Cardiac muscle`,`Skeletal muscle`], ans:3, exp:`Skeletal muscle is striated, voluntary muscle attached to bones by tendons, responsible for movement of the skeleton.` },
      { q:`Cardiac muscle is found exclusively in the:`, ch:[`Heart`,`Blood vessel walls`,`Skeletal muscles`,`Digestive tract`], ans:0, exp:`Cardiac muscle is a specialized, involuntary, striated muscle found only in the walls of the heart, allowing it to contract rhythmically without conscious control.` },
      { q:`Smooth muscle is typically found in which of these locations?`, ch:[`Attached to bones`,`Walls of internal organs such as the intestines and blood vessels`,`The heart only`,`Skin surface`], ans:1, exp:`Smooth muscle is involuntary and non-striated, lining the walls of hollow internal organs like the intestines, stomach, and blood vessels, controlling processes like peristalsis.` },
      { q:`A muscle that works in opposition to another, such that when one contracts the other relaxes, is called a(n):`, ch:[`Fixator`,`Synergist`,`Antagonist`,`Agonist`], ans:2, exp:`Antagonistic muscle pairs (e.g., biceps and triceps) work in opposition: when the agonist contracts to produce a movement, the antagonist relaxes and vice versa.` },
      { q:`Which structural protein filaments slide past each other during muscle contraction, according to the sliding filament theory?`, ch:[`Keratin and tubulin`,`Hemoglobin and myoglobin`,`Collagen and elastin`,`Actin and myosin`], ans:3, exp:`The sliding filament theory describes how thin actin filaments slide past thick myosin filaments, shortening the sarcomere and producing muscle contraction.` },
      { q:`Tendons connect muscle to:`, ch:[`Bone`,`Other muscle only`,`Skin`,`Cartilage exclusively`], ans:0, exp:`Tendons are tough connective tissue structures that anchor skeletal muscle to bone, transmitting the force of muscle contraction to move the skeleton.` },
      { q:`The biceps brachii primarily functions to:`, ch:[`Extend the elbow`,`Flex the elbow`,`Rotate the hip`,`Extend the knee`], ans:1, exp:`The biceps brachii is located on the front of the upper arm and contracts to flex the elbow joint, bringing the forearm toward the shoulder.` },
      { q:`Muscle fatigue during intense exercise is commonly associated with the buildup of:`, ch:[`Bile`,`Oxygen`,`Lactic acid (lactate) from anaerobic metabolism`,`Glucose`], ans:2, exp:`During intense exercise, when oxygen supply is insufficient, muscles rely on anaerobic glycolysis, producing lactate, which is associated with the sensation of muscle fatigue.` },
      { q:`Which term describes a muscle contraction that generates force without shortening the muscle, such as holding a plank position?`, ch:[`Eccentric lengthening`,`Reflex contraction`,`Isotonic contraction`,`Isometric contraction`], ans:3, exp:`Isometric contractions generate muscular tension without a change in muscle length, as opposed to isotonic contractions, which involve shortening or lengthening while generating force.` },
      { q:`A motor unit is best defined as:`, ch:[`A motor neuron and all the muscle fibers it innervates`,`A group of tendons`,`The connective tissue surrounding a muscle`,`A single muscle fiber`], ans:0, exp:`A motor unit consists of one motor neuron and every muscle fiber it controls; when the neuron fires, all fibers in that unit contract together.` },
      { q:`Striations visible under a microscope are characteristic of which muscle type(s)?`, ch:[`Smooth muscle only`,`Skeletal and cardiac muscle`,`Smooth and cardiac muscle`,`No muscle types show striations`], ans:1, exp:`Both skeletal and cardiac muscle appear striated (banded) under a microscope due to the highly organized arrangement of actin and myosin filaments in sarcomeres; smooth muscle lacks this organization and appears non-striated.` },
      { q:`ATP is required in muscle contraction primarily to:`, ch:[`Convert lactate to glucose`,`Directly cause muscle relaxation only`,`Break the actin-myosin cross-bridge and reset myosin for the next power stroke`,`Build new muscle fibers instantly`], ans:2, exp:`ATP binding to myosin heads releases them from actin (cross-bridge detachment) and re-cocks the myosin head, allowing repeated cycles of contraction; without ATP, muscles remain in rigor (as seen in rigor mortis).` },
      { q:`Which mineral ion is essential for triggering muscle contraction by binding to troponin?`, ch:[`Chloride`,`Sodium`,`Potassium`,`Calcium`], ans:3, exp:`Calcium ions released from the sarcoplasmic reticulum bind to troponin, causing a conformational shift that moves tropomyosin and exposes myosin-binding sites on actin.` },
    ]
  },
  {
    id:'bb106', cat:'Life Sciences', title:'Human Respiratory System', diff:'Easy',
    qs:[
      { q:`What is the primary function of the respiratory system?`, ch:[`Exchanging oxygen and carbon dioxide between air and blood`,`Filtering blood cells`,`Producing hormones`,`Digesting food`], ans:0, exp:`The respiratory system brings oxygen into the body and removes carbon dioxide, primarily through gas exchange occurring in the alveoli of the lungs.` },
      { q:`Gas exchange in the lungs occurs across the walls of the:`, ch:[`Bronchi`,`Alveoli`,`Larynx`,`Trachea`], ans:1, exp:`Alveoli are tiny, thin-walled air sacs surrounded by capillaries, providing a large surface area where oxygen and carbon dioxide diffuse between air and blood.` },
      { q:`The muscle primarily responsible for driving breathing by contracting and flattening during inhalation is the:`, ch:[`Biceps`,`Intercostal cartilage`,`Diaphragm`,`Trapezius`], ans:2, exp:`The diaphragm is a dome-shaped muscle beneath the lungs; it contracts and flattens during inhalation, increasing thoracic volume and drawing air into the lungs.` },
      { q:`Air travels through which structure immediately after passing through the pharynx and larynx?`, ch:[`Capillaries`,`Diaphragm`,`Alveoli`,`Trachea`], ans:3, exp:`After the larynx, air passes into the trachea (windpipe), which branches into the two bronchi leading to each lung.` },
      { q:`During inhalation, thoracic (chest cavity) volume:`, ch:[`Increases, decreasing pressure and drawing air in`,`Stays the same`,`Doubles instantly`,`Decreases, increasing pressure`], ans:0, exp:`Diaphragm contraction increases thoracic volume, which decreases internal air pressure relative to the atmosphere, causing air to flow into the lungs.` },
      { q:`Which structure prevents food from entering the trachea during swallowing?`, ch:[`Uvula`,`Epiglottis`,`Esophagus`,`Larynx`], ans:1, exp:`The epiglottis is a flap of tissue that folds down over the trachea during swallowing, directing food into the esophagus and preventing aspiration.` },
      { q:`Oxygen in the blood is primarily transported by binding to:`, ch:[`Plasma proteins`,`White blood cells`,`Hemoglobin in red blood cells`,`Platelets`], ans:2, exp:`Hemoglobin, a protein found in red blood cells, binds oxygen in the lungs and releases it to tissues, making it the primary oxygen transport molecule in blood.` },
      { q:`The bronchi eventually branch into smaller tubes called:`, ch:[`Capillaries`,`Pleura`,`Alveoli directly`,`Bronchioles`], ans:3, exp:`Bronchi divide into progressively smaller bronchioles, which ultimately lead to clusters of alveoli where gas exchange occurs.` },
      { q:`The thin membrane surrounding the lungs that reduces friction during breathing is called the:`, ch:[`Pleura`,`Pericardium`,`Meninges`,`Peritoneum`], ans:0, exp:`The pleura is a double-layered membrane surrounding each lung; the fluid between its layers reduces friction as the lungs expand and contract during breathing.` },
      { q:`Which of these is primarily responsible for stimulating the urge to breathe?`, ch:[`Low blood oxygen levels alone in all cases`,`Rising carbon dioxide levels (and resulting decrease in blood pH), sensed by chemoreceptors`,`High blood glucose`,`Body temperature changes only`], ans:1, exp:`Chemoreceptors primarily detect rising CO2 levels (and the associated drop in blood pH), which is the main stimulus driving the brain's respiratory control centers to increase breathing rate.` },
      { q:`Asthma is a respiratory condition characterized by:`, ch:[`Complete paralysis of the diaphragm`,`Permanent destruction of alveoli`,`Inflammation and narrowing of the airways, making breathing difficult`,`Excess red blood cell production`], ans:2, exp:`Asthma involves inflammation, increased mucus production, and constriction of bronchial smooth muscle, narrowing airways and causing wheezing and difficulty breathing.` },
      { q:`Approximately what percentage of the air we inhale is oxygen?`, ch:[`~4%`,`~60%`,`~78%`,`~21%`], ans:3, exp:`Atmospheric air is roughly 78% nitrogen and about 21% oxygen, with small amounts of carbon dioxide, argon, and other gases.` },
      { q:`Cilia lining the trachea and bronchi primarily function to:`, ch:[`Sweep mucus and trapped particles/debris up and out of the airway`,`Produce surfactant`,`Contract during breathing to move air`,`Absorb oxygen directly`], ans:0, exp:`Cilia are tiny hair-like projections that beat in coordinated waves to move mucus (which traps dust, pathogens, and debris) up and out of the respiratory tract.` },
    ]
  },
  {
    id:'bb107', cat:'Life Sciences', title:'Human Digestive System', diff:'Easy',
    qs:[
      { q:`What is the primary function of the digestive system?`, ch:[`Producing red blood cells`,`Breaking down food into absorbable nutrients`,`Filtering waste from blood`,`Regulating body temperature`], ans:1, exp:`The digestive system mechanically and chemically breaks down food into smaller molecules that can be absorbed into the bloodstream and used by cells.` },
      { q:`Which enzyme, found in saliva, begins the chemical digestion of starch in the mouth?`, ch:[`Trypsin`,`Pepsin`,`Amylase`,`Lipase`], ans:2, exp:`Salivary amylase begins breaking down starch into smaller sugars while food is still in the mouth, before further digestion continues in the small intestine.` },
      { q:`Chemical digestion of proteins begins primarily in the:`, ch:[`Large intestine`,`Esophagus`,`Mouth`,`Stomach, via pepsin activated by stomach acid`], ans:3, exp:`In the stomach, hydrochloric acid activates pepsinogen into pepsin, which begins breaking down proteins into smaller peptide fragments.` },
      { q:`Most nutrient absorption occurs in the:`, ch:[`Small intestine`,`Large intestine`,`Stomach`,`Esophagus`], ans:0, exp:`The small intestine, with its highly folded lining and villi/microvilli, provides a huge surface area where most digestion completion and nutrient absorption occurs.` },
      { q:`Villi and microvilli in the small intestine primarily function to:`, ch:[`Neutralize stomach acid`,`Increase surface area for nutrient absorption`,`Store bile`,`Produce digestive enzymes exclusively`], ans:1, exp:`Villi (finger-like folds) and microvilli (even smaller projections on villi cells) dramatically increase the internal surface area of the small intestine, maximizing nutrient absorption.` },
      { q:`Bile, which helps emulsify fats for digestion, is produced by the:`, ch:[`Stomach`,`Pancreas`,`Liver`,`Gallbladder`], ans:2, exp:`Bile is produced by the liver and stored/concentrated in the gallbladder; it is released into the small intestine to emulsify fats, aiding lipase activity.` },
      { q:`The pancreas contributes to digestion primarily by releasing:`, ch:[`Hydrochloric acid into the esophagus`,`Insulin into the small intestine for digestion`,`Bile into the stomach`,`Digestive enzymes and bicarbonate into the small intestine`], ans:3, exp:`The pancreas secretes digestive enzymes (for carbohydrates, proteins, and fats) and bicarbonate, which neutralizes acidic chyme entering the small intestine from the stomach.` },
      { q:`Peristalsis refers to:`, ch:[`Wave-like muscle contractions that move food through the digestive tract`,`The absorption of water in the large intestine`,`The storage of bile in the gallbladder`,`The production of stomach acid`], ans:0, exp:`Peristalsis is the rhythmic, wave-like contraction of smooth muscle in the digestive tract walls that propels food from the esophagus through the intestines.` },
      { q:`The primary function of the large intestine is to:`, ch:[`Digest proteins`,`Absorb water and electrolytes and compact waste into feces`,`Absorb the majority of nutrients`,`Produce bile`], ans:1, exp:`The large intestine (colon) absorbs remaining water and electrolytes from indigestible material and houses bacteria, forming and storing feces before elimination.` },
      { q:`Which stomach cells secrete hydrochloric acid?`, ch:[`Mucous cells only`,`Chief cells`,`Parietal cells`,`Goblet cells`], ans:2, exp:`Parietal cells in the stomach lining secrete hydrochloric acid, which lowers stomach pH, activates pepsinogen, and helps kill ingested pathogens.` },
      { q:`Which of the following best describes the role of the esophagus?`, ch:[`It produces digestive enzymes`,`It stores food long-term`,`It absorbs nutrients`,`It transports food from the pharynx to the stomach via peristalsis`], ans:3, exp:`The esophagus is a muscular tube that uses peristaltic contractions to move swallowed food from the throat down to the stomach.` },
      { q:`Beneficial gut bacteria residing in the large intestine contribute to health by:`, ch:[`Synthesizing certain vitamins (like vitamin K) and aiding fiber fermentation`,`Directly absorbing all nutrients for the host`,`Preventing the stomach from producing acid`,`Producing all necessary digestive enzymes for protein digestion`], ans:0, exp:`Gut microbiota help ferment indigestible fiber, produce short-chain fatty acids, and synthesize vitamins such as vitamin K and some B vitamins, benefiting the host.` },
      { q:`A deficiency in lactase enzyme production leads to difficulty digesting:`, ch:[`Fats`,`Lactose (milk sugar)`,`Proteins`,`Starch`], ans:1, exp:`Lactase breaks down lactose into glucose and galactose; without sufficient lactase, undigested lactose causes symptoms of lactose intolerance such as bloating and diarrhea.` },
    ]
  },
  {
    id:'bb108', cat:'Life Sciences', title:'Human Urinary & Renal System Basics', diff:'Easy',
    qs:[
      { q:`What is the primary function of the kidneys?`, ch:[`Storing urine`,`Producing digestive enzymes`,`Filtering blood to remove waste and regulate fluid/electrolyte balance`,`Producing red blood cells exclusively`], ans:2, exp:`The kidneys filter blood to remove metabolic wastes (like urea), regulate water and electrolyte balance, and help control blood pressure and pH.` },
      { q:`The functional unit of the kidney, where filtration occurs, is called the:`, ch:[`Bladder`,`Urethra`,`Ureter`,`Nephron`], ans:3, exp:`Each kidney contains roughly a million nephrons, the microscopic structures that filter blood and form urine.` },
      { q:`Urine travels from the kidneys to the bladder through the:`, ch:[`Ureters`,`Renal artery`,`Renal vein`,`Urethra`], ans:0, exp:`Ureters are muscular tubes that carry urine via peristaltic contractions from each kidney down to the urinary bladder for storage.` },
      { q:`Urine exits the body from the bladder through the:`, ch:[`Renal pelvis`,`Urethra`,`Glomerulus`,`Ureter`], ans:1, exp:`The urethra is the tube through which urine passes from the bladder to outside the body during urination.` },
      { q:`Within the nephron, the cluster of capillaries where blood is initially filtered is called the:`, ch:[`Collecting duct`,`Bowman's capsule`,`Glomerulus`,`Loop of Henle`], ans:2, exp:`The glomerulus is a tuft of capillaries where blood pressure forces water and small solutes out of the blood and into Bowman's capsule, beginning urine formation.` },
      { q:`Which nephron structure is primarily responsible for creating a concentration gradient that allows the kidney to concentrate urine?`, ch:[`Renal artery`,`Bowman's capsule`,`Glomerulus`,`Loop of Henle`], ans:3, exp:`The Loop of Henle establishes an osmotic gradient in the kidney's medulla, allowing water reabsorption from the collecting duct and thus concentration of urine.` },
      { q:`Substances such as glucose and amino acids are normally reabsorbed back into the blood primarily in the:`, ch:[`Proximal convoluted tubule`,`Ureter`,`Bladder`,`Glomerulus`], ans:0, exp:`The proximal convoluted tubule reabsorbs most filtered glucose, amino acids, and a large fraction of water and ions back into the bloodstream.` },
      { q:`The presence of glucose in urine (glycosuria) is commonly associated with:`, ch:[`Normal healthy kidney function`,`Diabetes mellitus, when blood glucose exceeds the kidney's reabsorption capacity`,`Dehydration only`,`Excess protein intake`], ans:1, exp:`When blood glucose levels are very high, as in uncontrolled diabetes, the amount filtered exceeds the kidney tubules' reabsorption capacity, so glucose appears in the urine.` },
      { q:`Antidiuretic hormone (ADH) primarily acts on the kidneys to:`, ch:[`Stop urine production entirely`,`Increase water excretion`,`Increase water reabsorption, producing more concentrated urine`,`Increase glucose reabsorption only`], ans:2, exp:`ADH increases the permeability of the collecting ducts to water, promoting water reabsorption back into the blood and reducing urine volume when the body needs to conserve water.` },
      { q:`Which waste product, derived from protein/amino acid breakdown, is a major component of urine?`, ch:[`Bile pigments`,`Cholesterol`,`Glucose`,`Urea`], ans:3, exp:`Urea is produced in the liver from ammonia generated during amino acid breakdown, and is excreted by the kidneys as a major nitrogenous waste product in urine.` },
      { q:`The kidneys help regulate blood pressure in part by releasing the enzyme/hormone:`, ch:[`Renin`,`Pepsin`,`Amylase`,`Insulin`], ans:0, exp:`Renin, released by the kidneys in response to low blood pressure or low blood volume, triggers the renin-angiotensin-aldosterone pathway, which raises blood pressure.` },
      { q:`Which of the following would most directly indicate impaired kidney filtering function on a blood test?`, ch:[`Low white blood cell count`,`Elevated blood urea nitrogen (BUN) and creatinine`,`Low blood glucose`,`High hemoglobin`], ans:1, exp:`When kidneys fail to filter waste effectively, nitrogenous wastes like urea and creatinine build up in the blood, so elevated BUN and creatinine are common markers of reduced kidney function.` },
    ]
  },
  {
    id:'bb109', cat:'Life Sciences', title:'Human Reproductive System Basics', diff:'Easy',
    qs:[
      { q:`Where does sperm production (spermatogenesis) primarily occur?`, ch:[`Vas deferens`,`Prostate gland`,`Seminiferous tubules of the testes`,`Epididymis`], ans:2, exp:`Spermatogenesis occurs within the seminiferous tubules inside the testes, where germ cells undergo meiosis to form mature sperm.` },
      { q:`After production, sperm mature and are stored in the:`, ch:[`Urethra`,`Bladder`,`Prostate`,`Epididymis`], ans:3, exp:`Sperm travel from the seminiferous tubules to the epididymis, a coiled tube where they mature and are stored before ejaculation.` },
      { q:`In the female reproductive system, egg cells (ova) are produced and stored in the:`, ch:[`Ovaries`,`Cervix`,`Uterus`,`Fallopian tubes`], ans:0, exp:`Ovaries contain follicles that house immature egg cells; each month one egg typically matures and is released during ovulation.` },
      { q:`Fertilization of an egg by sperm normally occurs in the:`, ch:[`Uterus`,`Fallopian tube (oviduct)`,`Vagina`,`Ovary`], ans:1, exp:`Fertilization typically occurs in the fallopian tube, where the released egg meets sperm that have traveled up from the vagina through the uterus.` },
      { q:`After fertilization, the embryo typically implants in the lining of the:`, ch:[`Ovary`,`Cervix`,`Uterus (endometrium)`,`Fallopian tube, permanently`], ans:2, exp:`The fertilized egg travels to the uterus and implants into the thickened endometrial lining, where it will develop throughout pregnancy.` },
      { q:`Which hormone triggers ovulation (the release of an egg from the ovary)?`, ch:[`Insulin`,`Testosterone`,`Melatonin`,`A surge in luteinizing hormone (LH)`], ans:3, exp:`A sharp surge in luteinizing hormone (LH), released by the pituitary gland, triggers the ovary to release a mature egg during the menstrual cycle.` },
      { q:`The primary male sex hormone, responsible for sperm production and secondary sexual characteristics, is:`, ch:[`Testosterone`,`Oxytocin`,`Estrogen`,`Progesterone`], ans:0, exp:`Testosterone, produced mainly by the testes, drives sperm production and the development of male secondary sexual characteristics such as facial hair and a deeper voice.` },
      { q:`If fertilization does not occur, the shedding of the uterine lining results in:`, ch:[`Ovulation`,`Menstruation`,`Implantation`,`Fertilization`], ans:1, exp:`Without fertilization and the resulting hormone support, the endometrial lining breaks down and is shed from the body as menstrual flow.` },
      { q:`The placenta, which forms during pregnancy, primarily functions to:`, ch:[`Produce breast milk`,`Produce sperm`,`Exchange nutrients, gases, and waste between mother and fetus`,`Store the egg before fertilization`], ans:2, exp:`The placenta is a temporary organ that allows the exchange of oxygen, nutrients, and waste products between maternal and fetal blood supplies without their blood directly mixing.` },
      { q:`Which structure connects the developing fetus to the placenta?`, ch:[`Fallopian tube`,`Cervix`,`Amniotic sac wall`,`Umbilical cord`], ans:3, exp:`The umbilical cord contains blood vessels connecting the fetus to the placenta, delivering nutrients and oxygen and removing waste.` },
      { q:`The average human gestation period (pregnancy) is approximately:`, ch:[`40 weeks (about 9 months)`,`6 weeks`,`18 months`,`4 months`], ans:0, exp:`Human gestation lasts approximately 40 weeks (about 9 months) from the last menstrual period to full-term birth.` },
      { q:`During the menstrual cycle, which hormone is primarily responsible for thickening and maintaining the uterine lining after ovulation?`, ch:[`Growth hormone`,`Progesterone`,`Testosterone`,`Follicle-stimulating hormone (FSH) alone`], ans:1, exp:`Progesterone, secreted by the corpus luteum after ovulation, maintains and thickens the endometrium to support potential implantation of a fertilized egg.` },
      { q:`Identical (monozygotic) twins result from:`, ch:[`Fertilization occurring in two different fallopian tubes`,`Two separate eggs fertilized by two separate sperm`,`A single fertilized egg splitting into two separate embryos`,`One egg fertilized twice`], ans:2, exp:`Monozygotic (identical) twins arise when a single fertilized egg (zygote) splits early in development into two embryos, resulting in genetically identical offspring.` },
    ]
  },
  {
    id:'bb110', cat:'Life Sciences', title:'Human Circulatory System Detail', diff:'Medium',
    qs:[
      { q:`Which chamber of the heart pumps oxygenated blood out to the rest of the body?`, ch:[`Right atrium`,`Right ventricle`,`Left atrium`,`Left ventricle`], ans:3, exp:`The left ventricle has the thickest muscular wall and pumps oxygen-rich blood out through the aorta to the entire systemic circulation.` },
      { q:`Blood returning from the body (deoxygenated) first enters the heart at the:`, ch:[`Right atrium`,`Left ventricle`,`Right ventricle`,`Left atrium`], ans:0, exp:`Deoxygenated blood from the body enters the right atrium via the superior and inferior vena cavae, before moving to the right ventricle and then the lungs.` },
      { q:`Which blood vessels carry blood away from the heart?`, ch:[`Veins`,`Arteries`,`Capillaries only`,`Venules only`], ans:1, exp:`By definition, arteries carry blood away from the heart (typically oxygenated, except the pulmonary artery), while veins return blood to the heart.` },
      { q:`Gas and nutrient exchange between blood and tissues occurs primarily across the walls of:`, ch:[`Arteries`,`Veins`,`Capillaries`,`The aorta`], ans:2, exp:`Capillaries have extremely thin, single-cell-layer walls, allowing efficient diffusion of oxygen, carbon dioxide, and nutrients between blood and surrounding tissue.` },
      { q:`Which valve separates the left atrium and left ventricle?`, ch:[`Aortic valve`,`Tricuspid valve`,`Pulmonary valve`,`Mitral (bicuspid) valve`], ans:3, exp:`The mitral (bicuspid) valve lies between the left atrium and left ventricle, preventing backflow of blood into the atrium during ventricular contraction.` },
      { q:`Pulmonary circulation refers to the pathway of blood:`, ch:[`Between the heart and the lungs for gas exchange`,`Through the liver only`,`Through the kidneys only`,`From the heart to the entire body and back`], ans:0, exp:`Pulmonary circulation carries deoxygenated blood from the right ventricle to the lungs for gas exchange, then returns oxygenated blood to the left atrium.` },
      { q:`The SA (sinoatrial) node is significant because it:`, ch:[`Filters blood`,`Acts as the heart's natural pacemaker, initiating each heartbeat`,`Produces red blood cells`,`Regulates blood pressure via hormones`], ans:1, exp:`The SA node, located in the right atrium, spontaneously generates electrical impulses that set the rhythm of the heartbeat, making it the heart's natural pacemaker.` },
      { q:`Which type of blood cell is primarily responsible for carrying oxygen?`, ch:[`White blood cells`,`Platelets`,`Red blood cells`,`Plasma proteins`], ans:2, exp:`Red blood cells (erythrocytes) contain hemoglobin, which binds oxygen in the lungs and delivers it to tissues throughout the body.` },
      { q:`Platelets are primarily responsible for:`, ch:[`Carrying oxygen`,`Producing antibodies`,`Fighting infection`,`Blood clotting`], ans:3, exp:`Platelets (thrombocytes) are cell fragments that aggregate at sites of vessel injury and participate in the clotting process to stop bleeding.` },
      { q:`Blood pressure is typically recorded as two numbers (e.g., 120/80); the top number represents:`, ch:[`Systolic pressure (ventricles contracting)`,`Pulse rate`,`Blood oxygen saturation`,`Diastolic pressure (ventricles relaxed)`], ans:0, exp:`Systolic pressure, the higher/top number, measures arterial pressure during ventricular contraction, while diastolic pressure (bottom number) measures pressure during ventricular relaxation.` },
      { q:`Veins typically contain valves primarily to:`, ch:[`Increase blood pressure`,`Prevent backflow of blood, especially against gravity`,`Produce blood cells`,`Filter toxins from blood`], ans:1, exp:`Because venous blood pressure is low, one-way valves in veins (especially in the limbs) prevent blood from flowing backward and help ensure return to the heart.` },
      { q:`Atherosclerosis is best described as:`, ch:[`Widening of veins`,`Thinning of artery walls`,`Buildup of fatty plaques within artery walls, narrowing them`,`Excessive red blood cell production`], ans:2, exp:`Atherosclerosis involves the accumulation of cholesterol-rich plaques within arterial walls, narrowing the lumen and restricting blood flow, increasing risk of heart attack and stroke.` },
      { q:`The largest artery in the human body, which carries oxygenated blood from the left ventricle to the body, is the:`, ch:[`Carotid artery`,`Pulmonary artery`,`Vena cava`,`Aorta`], ans:3, exp:`The aorta is the body's largest artery, receiving oxygenated blood directly from the left ventricle and distributing it via branching arteries throughout the body.` },
    ]
  },
  {
    id:'bb111', cat:'Life Sciences', title:'Human Nervous System Basics', diff:'Easy',
    qs:[
      { q:`The two main divisions of the nervous system are the:`, ch:[`Central and peripheral nervous systems`,`Sympathetic and parasympathetic systems only`,`Brain and spinal nervous systems`,`Sensory and motor nervous systems`], ans:0, exp:`The central nervous system (brain and spinal cord) processes information, while the peripheral nervous system (all nerves outside the CNS) connects the CNS to the rest of the body.` },
      { q:`The basic functional cell of the nervous system is the:`, ch:[`Osteocyte`,`Neuron`,`Myocyte`,`Erythrocyte`], ans:1, exp:`Neurons are specialized cells that transmit electrical and chemical signals, forming the basic functional units of the nervous system.` },
      { q:`Which part of a neuron receives incoming signals from other neurons?`, ch:[`Axon terminal`,`Axon`,`Dendrites`,`Myelin sheath`], ans:2, exp:`Dendrites are branching extensions of the neuron cell body that receive chemical signals from other neurons and convert them into electrical impulses.` },
      { q:`The gap between two neurons where neurotransmitters are released is called the:`, ch:[`Nucleus`,`Axon hillock`,`Node of Ranvier`,`Synapse`], ans:3, exp:`The synapse is the junction between two neurons (or a neuron and target cell) where neurotransmitters are released from the presynaptic terminal to signal the postsynaptic cell.` },
      { q:`Myelin sheaths, produced by Schwann cells and oligodendrocytes, primarily function to:`, ch:[`Speed up the conduction of electrical impulses along the axon`,`Store memories`,`Filter cerebrospinal fluid`,`Produce neurotransmitters`], ans:0, exp:`Myelin is an insulating layer around axons that allows electrical impulses to jump between gaps (nodes of Ranvier) via saltatory conduction, greatly increasing signal speed.` },
      { q:`The brain and spinal cord together make up the:`, ch:[`Autonomic nervous system`,`Central nervous system`,`Somatic nervous system`,`Peripheral nervous system`], ans:1, exp:`The central nervous system (CNS) consists of the brain and spinal cord, serving as the main processing and control center for the body.` },
      { q:`Which part of the brain is primarily responsible for coordinating balance and fine motor movement?`, ch:[`Hypothalamus`,`Cerebrum`,`Cerebellum`,`Medulla oblongata`], ans:2, exp:`The cerebellum, located at the back of the brain, coordinates voluntary movement, balance, and fine motor control.` },
      { q:`The brainstem structure that regulates vital involuntary functions like heart rate and breathing is the:`, ch:[`Corpus callosum`,`Cerebrum`,`Cerebellum`,`Medulla oblongata`], ans:3, exp:`The medulla oblongata, part of the brainstem, controls essential automatic functions including heart rate, breathing, and blood pressure.` },
      { q:`A reflex arc, such as pulling your hand away from a hot surface, typically bypasses conscious brain processing by routing the signal through the:`, ch:[`Spinal cord`,`Cerebellum only`,`Hypothalamus`,`Cerebrum only`], ans:0, exp:`Many reflexes are processed directly in the spinal cord via a reflex arc, allowing a rapid motor response before the signal even reaches the brain for conscious awareness.` },
      { q:`Which division of the peripheral nervous system controls involuntary functions like heart rate, digestion, and gland secretion?`, ch:[`Somatic nervous system`,`Autonomic nervous system`,`Central nervous system`,`Skeletal nervous system`], ans:1, exp:`The autonomic nervous system regulates involuntary bodily functions, including heart rate, digestion, and glandular secretions, and is further divided into sympathetic and parasympathetic branches.` },
      { q:`An action potential is generated when a neuron's membrane potential:`, ch:[`Is affected only by potassium efflux`,`Becomes more negative (hyperpolarizes) past a threshold`,`Reaches a threshold and rapidly depolarizes, largely due to sodium ion influx`,`Remains constant`], ans:2, exp:`When depolarization reaches a threshold, voltage-gated sodium channels open, causing rapid sodium influx and a sharp depolarization that constitutes the action potential.` },
      { q:`Neurotransmitters released from the presynaptic neuron cross the synapse and bind to receptors on the:`, ch:[`Myelin sheath`,`Glial cells exclusively`,`Presynaptic neuron only`,`Postsynaptic neuron`], ans:3, exp:`Neurotransmitters diffuse across the synaptic cleft and bind specific receptors on the postsynaptic neuron's membrane, triggering a new electrical or chemical response.` },
    ]
  },
  {
    id:'bb112', cat:'Life Sciences', title:'Human Endocrine System Basics', diff:'Medium',
    qs:[
      { q:`The endocrine system primarily communicates using:`, ch:[`Hormones released into the bloodstream`,`Direct physical contact between cells`,`Sound waves`,`Electrical impulses only`], ans:0, exp:`Endocrine glands secrete hormones directly into the bloodstream, which travel to target cells/organs elsewhere in the body to regulate their activity.` },
      { q:`Which gland is often called the "master gland" because it regulates many other endocrine glands?`, ch:[`Adrenal gland`,`Pituitary gland`,`Pancreas`,`Thyroid gland`], ans:1, exp:`The pituitary gland, located at the base of the brain, releases hormones that regulate the activity of many other endocrine glands, including the thyroid and adrenal glands.` },
      { q:`The thyroid gland primarily produces hormones that regulate:`, ch:[`Digestion of fats exclusively`,`Blood clotting`,`Metabolic rate`,`Immune response only`], ans:2, exp:`Thyroid hormones (T3 and T4) regulate the body's basal metabolic rate, influencing energy use, growth, and development.` },
      { q:`Insulin, produced by the pancreas, primarily functions to:`, ch:[`Regulate calcium levels`,`Stimulate the immune system`,`Raise blood glucose levels`,`Lower blood glucose levels by promoting cellular glucose uptake`], ans:3, exp:`Insulin is released when blood glucose is high; it promotes glucose uptake by cells (especially muscle and fat) and glycogen storage, lowering blood glucose levels.` },
      { q:`Glucagon, also produced by the pancreas, has which effect on blood glucose?`, ch:[`Raises it by stimulating glycogen breakdown in the liver`,`Has no effect`,`Only affects fat cells`,`Lowers it`], ans:0, exp:`Glucagon is released when blood glucose is low; it stimulates the liver to break down glycogen and release glucose into the blood, raising blood glucose levels.` },
      { q:`The adrenal glands release which hormone in response to acute stress, preparing the body for "fight or flight"?`, ch:[`Insulin`,`Epinephrine (adrenaline)`,`Thyroid hormone`,`Melatonin`], ans:1, exp:`In response to stress, the adrenal medulla releases epinephrine (adrenaline), increasing heart rate, blood pressure, and blood glucose availability for rapid action.` },
      { q:`Type 1 diabetes results from:`, ch:[`Overproduction of growth hormone`,`Underactive adrenal glands`,`The pancreas producing insufficient or no insulin, often due to autoimmune destruction of beta cells`,`Excess thyroid hormone production`], ans:2, exp:`Type 1 diabetes is typically caused by autoimmune destruction of insulin-producing beta cells in the pancreas, resulting in little or no insulin production.` },
      { q:`Growth hormone is secreted by the:`, ch:[`Adrenal cortex`,`Pancreas`,`Thyroid gland`,`Pituitary gland`], ans:3, exp:`Growth hormone (somatotropin) is produced by the anterior pituitary gland and stimulates growth in bones and tissues, particularly during childhood and adolescence.` },
      { q:`Hormones are best described as chemical messengers that:`, ch:[`Travel through the blood and act on distant target cells with specific receptors`,`Can only affect neurons`,`Act instantaneously with no delay`,`Only act on the cell that produced them`], ans:0, exp:`Hormones are secreted into the bloodstream and circulate throughout the body, but only affect target cells that possess the appropriate receptors for that hormone.` },
      { q:`Negative feedback is a common regulatory mechanism in the endocrine system in which:`, ch:[`Rising hormone levels stimulate even more hormone release`,`The output of a pathway inhibits further release of that hormone, maintaining homeostasis`,`Hormone levels are unaffected by the body's needs`,`Only positive feedback loops exist in hormone regulation`], ans:1, exp:`In negative feedback, a rise in a hormone (or its effect) suppresses further secretion of that hormone, keeping levels within a stable, healthy range — the predominant feedback pattern in the endocrine system.` },
      { q:`Which gland releases melatonin, a hormone involved in regulating sleep-wake cycles?`, ch:[`Parathyroid gland`,`Adrenal medulla`,`Pineal gland`,`Thymus`], ans:2, exp:`The pineal gland secretes melatonin, particularly in response to darkness, helping regulate circadian rhythms and the sleep-wake cycle.` },
      { q:`The parathyroid glands primarily regulate:`, ch:[`Heart rate`,`Water balance exclusively`,`Blood glucose`,`Blood calcium levels`], ans:3, exp:`Parathyroid hormone (PTH), released by the parathyroid glands, raises blood calcium levels by acting on bone, kidneys, and intestines.` },
    ]
  },
  {
    id:'bb113', cat:'Life Sciences', title:'The Five Senses', diff:'Easy',
    qs:[
      { q:`Light entering the eye is initially focused by the:`, ch:[`Cornea and lens`,`Optic nerve`,`Iris only`,`Retina`], ans:0, exp:`The cornea provides most of the eye's focusing power, with the lens making fine adjustments to focus light precisely onto the retina.` },
      { q:`Photoreceptor cells that detect light and color are located in the:`, ch:[`Cornea`,`Retina`,`Pupil`,`Sclera`], ans:1, exp:`The retina contains rod cells (detect light/dark, useful in dim light) and cone cells (detect color, useful in bright light), which convert light into neural signals.` },
      { q:`Which structure controls the amount of light entering the eye by adjusting pupil size?`, ch:[`Optic nerve`,`Lens`,`Iris`,`Retina`], ans:2, exp:`The iris is the colored, muscular part of the eye that contracts or relaxes to change the size of the pupil, controlling how much light enters.` },
      { q:`Sound waves are converted into electrical signals in the ear by structures within the:`, ch:[`Eardrum only`,`Outer ear`,`Middle ear bones (ossicles)`,`Cochlea of the inner ear`], ans:3, exp:`The cochlea, a fluid-filled spiral structure in the inner ear, contains hair cells that convert sound vibrations into electrical signals sent to the brain via the auditory nerve.` },
      { q:`The three tiny bones in the middle ear that amplify sound vibrations are collectively called the:`, ch:[`Ossicles (malleus, incus, stapes)`,`Semicircular canals`,`Cochlear hairs`,`Eustachian tubes`], ans:0, exp:`The malleus, incus, and stapes (ossicles) form a chain that mechanically amplifies vibrations from the eardrum and transmits them to the cochlea.` },
      { q:`Balance and equilibrium are primarily sensed by structures in the:`, ch:[`Cochlea`,`Semicircular canals of the inner ear`,`Outer ear`,`Eardrum`], ans:1, exp:`The semicircular canals, filled with fluid and lined with hair cells, detect rotational movement and changes in head position, helping maintain balance.` },
      { q:`Taste buds, which detect chemicals dissolved in saliva, are primarily located on the:`, ch:[`Lips`,`Roof of the mouth only`,`Tongue`,`Cheeks`], ans:2, exp:`Taste buds are concentrated on the tongue (with some also on the palate), containing receptor cells that detect sweet, salty, sour, bitter, and umami tastes.` },
      { q:`Olfactory receptors, responsible for the sense of smell, are located in the:`, ch:[`Outer ear`,`Tongue`,`Back of the throat`,`Upper nasal cavity`], ans:3, exp:`Olfactory receptor neurons line the upper region of the nasal cavity and detect airborne chemical molecules, sending signals to the brain's olfactory bulb.` },
      { q:`Which sense is most closely linked to taste, such that food often tastes bland when this sense is impaired (e.g., during a cold)?`, ch:[`Smell`,`Touch`,`Vision`,`Hearing`], ans:0, exp:`Smell and taste work closely together; much of what we perceive as "flavor" actually comes from odor molecules detected by olfactory receptors, which is why food tastes different with a stuffy nose.` },
      { q:`Which type of skin receptor is primarily responsible for detecting pain?`, ch:[`Meissner's corpuscles`,`Nociceptors`,`Pacinian corpuscles`,`Merkel cells`], ans:1, exp:`Nociceptors are specialized nerve endings that detect potentially damaging stimuli (mechanical, thermal, or chemical) and signal pain to the brain.` },
      { q:`Pacinian corpuscles in the skin are specialized to detect:`, ch:[`Pain only`,`Temperature only`,`Deep pressure and vibration`,`Light touch exclusively`], ans:2, exp:`Pacinian corpuscles are deep-skin receptors that respond rapidly to deep pressure and vibration, allowing detection of texture and mechanical disturbances.` },
      { q:`Cone cells in the retina are primarily responsible for:`, ch:[`Peripheral vision in the dark`,`Balance`,`Detecting motion only`,`Color vision and high visual acuity in bright light`], ans:3, exp:`Cone cells function best in bright light and are responsible for color vision and sharp visual detail, concentrated especially in the fovea.` },
      { q:`Rod cells in the retina are specialized for:`, ch:[`Detecting light in low-light (dim) conditions`,`Producing tears`,`Focusing light`,`Color detection in bright light`], ans:0, exp:`Rod cells are highly sensitive to light and enable vision in low-light conditions, though they do not distinguish color and provide lower visual acuity than cones.` },
    ]
  },
  {
    id:'bb114', cat:'Life Sciences', title:'Skin & the Integumentary System', diff:'Easy',
    qs:[
      { q:`Which of the following is NOT a primary function of the integumentary system?`, ch:[`Regulating body temperature`,`Producing red blood cells`,`Sensing touch, pressure, and temperature`,`Protecting against pathogens and injury`], ans:1, exp:`The integumentary system (skin, hair, nails) protects the body, helps regulate temperature, and provides sensory information, but it does not produce red blood cells — that occurs in bone marrow.` },
      { q:`The outermost layer of the skin is called the:`, ch:[`Subcutaneous layer`,`Dermis`,`Epidermis`,`Hypodermis`], ans:2, exp:`The epidermis is the thin, outermost layer of skin, composed mainly of keratinocytes, and it acts as the primary protective barrier against the environment.` },
      { q:`Which layer of skin contains blood vessels, hair follicles, and sweat glands?`, ch:[`Stratum corneum only`,`Cuticle`,`Epidermis`,`Dermis`], ans:3, exp:`The dermis, located beneath the epidermis, contains blood vessels, nerve endings, hair follicles, sweat glands, and sebaceous (oil) glands.` },
      { q:`The protein that makes up the tough, protective outer layer of skin, hair, and nails is:`, ch:[`Keratin`,`Elastin`,`Myosin`,`Collagen`], ans:0, exp:`Keratin is a fibrous, water-resistant protein produced by keratinocytes that provides structural strength and protection to the skin's outer layer, hair, and nails.` },
      { q:`Sweating helps regulate body temperature primarily through the process of:`, ch:[`Conduction`,`Evaporative cooling`,`Radiation only`,`Insulation`], ans:1, exp:`When sweat evaporates from the skin's surface, it removes heat energy from the body, cooling it down — a key mechanism for thermoregulation during heat or exercise.` },
      { q:`Melanin, the pigment responsible for skin color and UV protection, is produced by:`, ch:[`Adipocytes`,`Keratinocytes`,`Melanocytes`,`Fibroblasts`], ans:2, exp:`Melanocytes, located in the epidermis, produce melanin, which gives skin its color and helps absorb and block harmful UV radiation from sunlight.` },
      { q:`Which skin structure is responsible for producing an oily substance that lubricates skin and hair?`, ch:[`Hair follicles alone`,`Merkel cells`,`Sweat glands`,`Sebaceous glands`], ans:3, exp:`Sebaceous glands secrete sebum, an oily substance that lubricates and waterproofs the skin and hair, and has mild antibacterial properties.` },
      { q:`The layer of fat and connective tissue beneath the dermis, providing insulation and cushioning, is the:`, ch:[`Hypodermis (subcutaneous layer)`,`Cuticle`,`Epidermis`,`Stratum corneum`], ans:0, exp:`The hypodermis (subcutaneous layer) lies beneath the dermis and contains adipose (fat) tissue, providing insulation, energy storage, and cushioning.` },
      { q:`Vitamin D synthesis in the skin is triggered primarily by exposure to:`, ch:[`Visible light only`,`Ultraviolet (UV) light`,`Cold temperatures`,`Humidity`], ans:1, exp:`UV radiation from sunlight converts a cholesterol-derived precursor in the skin into vitamin D3, which is further processed by the liver and kidneys into its active form.` },
      { q:`Which of the following best describes the skin's role as a barrier against infection?`, ch:[`It has no role in immune defense`,`It produces antibodies exclusively`,`Its physical structure and slightly acidic surface inhibit the growth and entry of pathogens`,`It only prevents water loss, not pathogen entry`], ans:2, exp:`The skin's tightly packed keratinized cells and slightly acidic pH create a physical and chemical barrier that helps prevent most pathogens from entering the body, making it a key part of innate immunity.` },
      { q:`A first-degree burn typically affects which layer(s) of skin?`, ch:[`Epidermis and full dermis`,`Hypodermis only`,`Muscle tissue`,`Epidermis only`], ans:3, exp:`A first-degree burn (like a mild sunburn) damages only the epidermis, causing redness and pain without blistering, and usually heals without scarring.` },
      { q:`Nails are composed primarily of:`, ch:[`Hardened keratin`,`Melanin`,`Adipose tissue`,`Collagen`], ans:0, exp:`Nails are made of tightly packed, hardened keratin produced by cells in the nail matrix, forming a protective covering over fingertips and toes.` },
    ]
  },
  {
    id:'bb115', cat:'Life Sciences', title:'Bacteria: Structure & Classification', diff:'Easy',
    qs:[
      { q:`Bacteria are classified as which type of organism based on cell structure?`, ch:[`Eukaryotic`,`Prokaryotic`,`Multicellular only`,`Viral`], ans:1, exp:`Bacteria are prokaryotes, meaning their cells lack a membrane-bound nucleus and other membrane-bound organelles, unlike eukaryotic cells.` },
      { q:`The genetic material of a typical bacterium is found in a region called the:`, ch:[`Golgi body`,`Nucleus`,`Nucleoid`,`Nucleolus`], ans:2, exp:`Bacterial DNA is typically a single circular chromosome located in an unbound region of the cytoplasm called the nucleoid, rather than enclosed in a nuclear membrane.` },
      { q:`Small, circular pieces of extrachromosomal DNA that many bacteria carry, often conferring traits like antibiotic resistance, are called:`, ch:[`Flagella`,`Pili`,`Ribosomes`,`Plasmids`], ans:3, exp:`Plasmids are small, circular DNA molecules separate from the main bacterial chromosome; they can carry genes for antibiotic resistance and can be transferred between bacteria.` },
      { q:`The Gram stain technique classifies bacteria based primarily on differences in their:`, ch:[`Cell wall structure`,`DNA sequence`,`Metabolic rate`,`Flagella number`], ans:0, exp:`Gram staining distinguishes bacteria by cell wall composition: Gram-positive bacteria have a thick peptidoglycan layer that retains crystal violet stain (appearing purple), while Gram-negative bacteria have a thinner peptidoglycan layer and an outer membrane, appearing pink after the stain washes out.` },
      { q:`Which structure allows some bacteria to move by rotating like a propeller?`, ch:[`Pili`,`Flagella`,`Cell wall`,`Capsule`], ans:1, exp:`Flagella are whip-like appendages that rotate to propel bacteria through liquid environments, aiding motility.` },
      { q:`A bacterial capsule, when present, primarily functions to:`, ch:[`Perform photosynthesis`,`Produce ATP`,`Help the bacterium evade the host immune system and adhere to surfaces`,`Store genetic material`], ans:2, exp:`The capsule is a protective outer layer of polysaccharide that can help bacteria resist phagocytosis by immune cells and adhere to surfaces, contributing to virulence.` },
      { q:`Binary fission is the process by which bacteria:`, ch:[`Undergo sexual reproduction`,`Form spores exclusively`,`Exchange genetic material`,`Reproduce asexually by dividing into two identical cells`], ans:3, exp:`Binary fission is asexual reproduction in which a bacterial cell duplicates its DNA and divides into two genetically identical daughter cells.` },
      { q:`Which of these best describes an obligate anaerobe?`, ch:[`An organism that is harmed or killed by the presence of oxygen`,`An organism that can survive with or without oxygen`,`An organism that only lives in extreme heat`,`An organism that requires oxygen to survive`], ans:0, exp:`Obligate anaerobes cannot tolerate oxygen and are damaged or killed by its presence, relying entirely on anaerobic metabolic pathways for energy.` },
      { q:`Bacterial conjugation is a process in which bacteria:`, ch:[`Are infected by a virus`,`Transfer genetic material directly between two cells via a pilus`,`Divide into two daughter cells`,`Take up DNA from the environment`], ans:1, exp:`Conjugation involves direct cell-to-cell contact, typically via a pilus, through which one bacterium transfers a copy of a plasmid to another, contributing to genetic diversity and antibiotic resistance spread.` },
      { q:`Antibiotics such as penicillin work by targeting:`, ch:[`Human DNA replication`,`Human cell membranes`,`Bacterial cell wall synthesis`,`Viral capsids`], ans:2, exp:`Penicillin and related antibiotics inhibit synthesis of the bacterial cell wall (specifically peptidoglycan cross-linking), which is present in bacteria but absent in human cells, making the drug selectively toxic to bacteria.` },
      { q:`Some bacteria can form highly resistant dormant structures called endospores primarily to:`, ch:[`Enhance photosynthesis`,`Increase motility`,`Reproduce more quickly`,`Survive extreme environmental conditions such as heat, desiccation, or lack of nutrients`], ans:3, exp:`Endospores are tough, dormant structures formed by certain bacteria (like Bacillus and Clostridium species) that allow survival through harsh conditions until favorable conditions return.` },
      { q:`Which shape classification describes rod-shaped bacteria?`, ch:[`Bacillus`,`Spirillum`,`Vibrio`,`Coccus`], ans:0, exp:`Bacilli are rod-shaped bacteria; cocci are spherical, spirilla are spiral-shaped, and vibrios are comma-shaped — these terms describe basic bacterial morphology.` },
    ]
  },
  {
    id:'bb116', cat:'Life Sciences', title:'Viruses: Structure & Classification', diff:'Easy',
    qs:[
      { q:`Which of the following best describes why viruses are often not classified as living organisms?`, ch:[`They lack any genetic material`,`They cannot reproduce independently and require a host cell's machinery`,`They are too small to be observed`,`They do not cause disease`], ans:1, exp:`Viruses lack independent metabolism and cannot replicate on their own; they must hijack a host cell's ribosomes and other machinery to reproduce, which is a key reason they are often excluded from the tree of life as traditionally defined.` },
      { q:`The protein coat that surrounds and protects a virus's genetic material is called the:`, ch:[`Cytoplasm`,`Envelope`,`Capsid`,`Nucleoid`], ans:2, exp:`The capsid is a protein shell made of repeating protein subunits (capsomeres) that encloses and protects the viral genetic material (DNA or RNA).` },
      { q:`A viral genome may consist of:`, ch:[`Protein exclusively`,`DNA only`,`RNA only`,`Either DNA or RNA, but never both`], ans:3, exp:`Unlike cellular organisms (which always use DNA as their primary genetic material), viruses may have either a DNA or RNA genome, but not both, and it can be single- or double-stranded.` },
      { q:`Some viruses, such as influenza, have an outer lipid membrane derived from the host cell called the:`, ch:[`Envelope`,`Tail fiber`,`Nucleocapsid core only`,`Capsid`], ans:0, exp:`Enveloped viruses acquire an outer lipid membrane (envelope), often studded with viral proteins, when they bud from a host cell membrane; this envelope can be disrupted by soap or alcohol-based disinfectants.` },
      { q:`Bacteriophages are viruses that specifically infect:`, ch:[`Plant cells`,`Bacteria`,`Fungi`,`Human cells`], ans:1, exp:`Bacteriophages ("phages") are viruses that specifically infect and replicate within bacterial cells, and are widely studied in molecular biology and increasingly explored as antibiotic alternatives.` },
      { q:`In the lytic cycle of viral replication, the host cell ultimately:`, ch:[`Divides into two daughter host cells`,`Survives and continues normal function`,`Bursts (lyses), releasing new virus particles`,`Becomes a permanent part of the viral genome`], ans:2, exp:`In the lytic cycle, the virus hijacks the host cell to produce many new viral particles, and the cell eventually bursts open (lyses), releasing the new viruses to infect other cells.` },
      { q:`In the lysogenic cycle, viral genetic material:`, ch:[`Cannot be replicated`,`Is destroyed by host enzymes`,`Immediately destroys the host cell`,`Integrates into the host genome and is passed on as the cell divides, often remaining dormant`], ans:3, exp:`During lysogeny, viral DNA integrates into the host chromosome as a "prophage" and replicates along with the host DNA during cell division, potentially remaining dormant before eventually re-entering a lytic cycle.` },
      { q:`Retroviruses, such as HIV, are unique in that they:`, ch:[`Use reverse transcriptase to convert their RNA genome into DNA inside the host cell`,`Cannot infect human cells`,`Replicate without any host cell machinery`,`Have a DNA genome that mutates rapidly`], ans:0, exp:`Retroviruses carry the enzyme reverse transcriptase, which converts their single-stranded RNA genome into double-stranded DNA that can then integrate into the host cell's genome.` },
      { q:`Antibiotics are generally ineffective against viral infections because antibiotics:`, ch:[`Destroy human cells directly`,`Target bacterial structures/processes (like cell walls) that viruses do not have`,`Are too weak to kill any pathogen`,`Only work on fungi`], ans:1, exp:`Antibiotics target structures and processes specific to bacteria (such as cell wall synthesis or bacterial ribosomes), which viruses do not possess, making antibiotics ineffective against viral infections like the common cold.` },
      { q:`Antigenic drift, which contributes to the need for updated flu vaccines each year, refers to:`, ch:[`Bacterial evolution only`,`Complete elimination of viral mutation`,`Small, gradual mutations in viral surface proteins over time`,`A virus losing its genetic material`], ans:2, exp:`Antigenic drift involves small, incremental mutations accumulating in viral surface proteins (like influenza hemagglutinin), gradually changing the virus enough that prior immunity becomes less effective, requiring updated vaccines.` },
      { q:`Which best describes a virus's basic components at minimum?`, ch:[`A full cell membrane and cytoplasm with organelles`,`Ribosomes and mitochondria`,`A nucleus and cell wall`,`Genetic material (DNA or RNA) enclosed in a protein capsid`], ans:3, exp:`At their simplest, viruses consist of genetic material enclosed within a protective protein capsid; they lack the cellular organelles, ribosomes, and metabolic machinery found in living cells.` },
      { q:`Vaccines against viral diseases often work by:`, ch:[`Exposing the immune system to a harmless form or part of the virus to build immune memory`,`Providing antibiotics to the body`,`Eliminating the need for an immune response`,`Directly killing the virus in the environment`], ans:0, exp:`Vaccines typically introduce an inactivated, weakened, or partial form of a pathogen (or its antigens) to safely train the immune system to recognize and respond quickly if exposed to the real pathogen later.` },
    ]
  },
  {
    id:'bb117', cat:'Life Sciences', title:'Fungi & Protists', diff:'Medium',
    qs:[
      { q:`Fungi obtain nutrients primarily by:`, ch:[`Performing photosynthesis`,`Secreting digestive enzymes externally and absorbing the resulting nutrients`,`Ingesting whole prey internally like animals`,`Fixing nitrogen from the air directly`], ans:1, exp:`Fungi are heterotrophic decomposers that secrete enzymes to break down organic material externally, then absorb the resulting simpler molecules (a mode of nutrition called absorptive heterotrophy).` },
      { q:`The main structural component of most fungal cell walls is:`, ch:[`Keratin`,`Cellulose`,`Chitin`,`Peptidoglycan`], ans:2, exp:`Fungal cell walls are made primarily of chitin, the same tough polysaccharide found in the exoskeletons of insects, distinguishing fungi from plants (cellulose) and bacteria (peptidoglycan).` },
      { q:`The thread-like structures that make up the body of a multicellular fungus are called:`, ch:[`Flagella`,`Rhizoids`,`Pseudopods`,`Hyphae`], ans:3, exp:`Hyphae are branching, thread-like filaments that make up the mycelium (the vegetative body) of most multicellular fungi, allowing them to absorb nutrients over a large surface area.` },
      { q:`Mushrooms are best described as:`, ch:[`The reproductive (fruiting) structure of certain fungi that produces spores`,`A type of bacteria`,`A photosynthetic plant structure`,`The entire fungal organism`], ans:0, exp:`A mushroom is the visible fruiting body of a fungus, produced for spore dispersal, while the majority of the organism exists as an underground or hidden network of hyphae (mycelium).` },
      { q:`Yeasts are unique among most fungi in that they are typically:`, ch:[`Multicellular and filamentous`,`Unicellular`,`Photosynthetic`,`Only pathogenic, never beneficial`], ans:1, exp:`Unlike most fungi, which are multicellular and filamentous, yeasts are typically unicellular fungi that reproduce by budding and are used in baking and brewing.` },
      { q:`Fungi primarily reproduce by producing:`, ch:[`Pollen`,`Seeds`,`Spores`,`Live young`], ans:2, exp:`Fungi reproduce (both sexually and asexually) by producing spores, which are small, often lightweight reproductive cells that can disperse and germinate into new fungal organisms.` },
      { q:`Which of the following best characterizes the group traditionally called "protists"?`, ch:[`Exclusively multicellular photosynthetic organisms`,`A subgroup of prokaryotes`,`A single, tightly unified evolutionary group`,`A diverse collection of mostly unicellular eukaryotes that don't fit into animal, plant, or fungi kingdoms`], ans:3, exp:`Protists are a highly diverse, largely unicellular group of eukaryotes; the category is more of a catch-all for organisms that don't fit neatly into the animal, plant, or fungal kingdoms, and is not considered a single natural evolutionary group.` },
      { q:`Amoebas move and capture food using temporary cytoplasmic extensions called:`, ch:[`Pseudopods`,`Hyphae`,`Cilia`,`Flagella`], ans:0, exp:`Amoebas use pseudopods ("false feet") — temporary extensions of cytoplasm — to move and to engulf food particles through a process called phagocytosis.` },
      { q:`Paramecium, a common protist, uses which structures for locomotion?`, ch:[`Pseudopods`,`Cilia`,`Hyphae`,`Roots`], ans:1, exp:`Paramecium is covered in many short, hair-like cilia that beat in coordinated waves, propelling the organism through water and helping sweep food into its oral groove.` },
      { q:`Algae, a group of photosynthetic protists, are ecologically important primarily because they:`, ch:[`Only live in soil`,`Decompose dead organic matter exclusively`,`Serve as major primary producers in aquatic ecosystems`,`Cause most human bacterial infections`], ans:2, exp:`Many algae are photosynthetic and serve as primary producers in aquatic food webs, forming the base of the food chain and contributing significantly to global oxygen production.` },
      { q:`Which of these organisms is a protist responsible for causing malaria?`, ch:[`Escherichia coli`,`Influenza virus`,`Saccharomyces (yeast)`,`Plasmodium`], ans:3, exp:`Plasmodium is a parasitic protist transmitted by Anopheles mosquitoes; it infects red blood cells and liver cells, causing malaria in humans.` },
      { q:`Lichens are a symbiotic association typically between:`, ch:[`A fungus and a photosynthetic partner (alga or cyanobacterium)`,`Two bacterial species`,`A virus and a bacterium`,`Two different animal species`], ans:0, exp:`Lichens result from a mutualistic relationship between a fungus, which provides structure and protection, and a photosynthetic alga or cyanobacterium, which supplies food via photosynthesis.` },
    ]
  },
  {
    id:'bb118', cat:'Life Sciences', title:'Infectious Disease Basics', diff:'Easy',
    qs:[
      { q:`A pathogen is best defined as:`, ch:[`Any beneficial microorganism`,`An organism or agent capable of causing disease`,`A type of antibody`,`A vitamin deficiency`], ans:1, exp:`A pathogen is any biological agent — bacteria, virus, fungus, protozoan, or prion — that can cause disease in a host organism.` },
      { q:`Diseases that can spread from one host to another are described as:`, ch:[`Autoimmune`,`Genetic`,`Communicable (infectious)`,`Non-communicable`], ans:2, exp:`Communicable (infectious) diseases can be transmitted directly or indirectly between hosts, unlike non-communicable diseases (such as most genetic disorders), which are not transmitted between individuals.` },
      { q:`Which of the following is an example of direct disease transmission?`, ch:[`Being bitten by an infected mosquito`,`Touching a contaminated doorknob`,`Drinking contaminated water`,`Physical contact with an infected person, such as touching or sexual contact`], ans:3, exp:`Direct transmission involves physical contact between an infected individual and a susceptible host (e.g., touching, kissing, sexual contact), as opposed to indirect transmission via vectors or contaminated objects/surfaces.` },
      { q:`An organism, such as a mosquito or tick, that transmits a pathogen from one host to another is called a:`, ch:[`Vector`,`Antigen`,`Antibody`,`Reservoir`], ans:0, exp:`A vector is a living organism (often an insect) that transmits an infectious pathogen between hosts, such as mosquitoes transmitting malaria or ticks transmitting Lyme disease.` },
      { q:`Koch's postulates are a set of criteria historically used to:`, ch:[`Determine the cause of a genetic disorder`,`Establish a causal relationship between a specific microbe and a specific disease`,`Measure blood pressure`,`Classify organisms into kingdoms`], ans:1, exp:`Koch's postulates provide criteria (the microbe must be found in all cases of the disease, isolated and grown in pure culture, cause disease when introduced into a healthy host, and be re-isolated from that host) to establish that a specific pathogen causes a specific disease.` },
      { q:`An epidemic refers to:`, ch:[`The complete eradication of a disease`,`A disease that occurs at a constant, expected baseline level in a population`,`A sudden increase in disease cases above what is normally expected in a region`,`A disease affecting only animals`], ans:2, exp:`An epidemic is a sudden, notable increase in the number of disease cases within a specific population or region beyond the baseline (endemic) level.` },
      { q:`A pandemic differs from an epidemic in that a pandemic:`, ch:[`Only refers to non-infectious diseases`,`Cannot be caused by viruses`,`Affects a smaller, more localized population`,`Spreads across multiple countries or continents, affecting a very large number of people`], ans:3, exp:`A pandemic is an epidemic that has spread across a much larger geographic area, such as multiple countries or worldwide, affecting a substantial portion of the population.` },
      { q:`Herd immunity occurs when:`, ch:[`A large enough proportion of a population is immune, reducing overall disease spread and indirectly protecting non-immune individuals`,`Only animals develop immunity`,`Vaccination causes the disease to spread faster`,`A single individual becomes immune to all diseases`], ans:0, exp:`When a sufficiently high percentage of a population is immune (via vaccination or prior infection), disease transmission is greatly reduced, indirectly protecting those who are not immune, including people who cannot be vaccinated.` },
      { q:`Antibiotic resistance in bacteria primarily develops through:`, ch:[`Bacteria intentionally avoiding antibiotics`,`Natural selection favoring bacteria with mutations or genes that survive antibiotic exposure`,`Antibiotics converting bacteria into viruses`,`Random spontaneous generation of new bacterial species`], ans:1, exp:`When antibiotics are used, bacteria with pre-existing resistance genes/mutations survive and reproduce while susceptible bacteria die, so resistant strains become more common over time through natural selection.` },
      { q:`Which of the following is generally considered the most effective way to prevent the spread of many infectious diseases?`, ch:[`Avoiding all outdoor activity`,`Ignoring symptoms until they worsen`,`Handwashing, vaccination, and proper sanitation`,`Taking antibiotics preventively for all illnesses`], ans:2, exp:`Basic public health measures — handwashing, vaccination, sanitation, and safe food/water handling — are highly effective, low-cost ways to reduce transmission of many infectious diseases.` },
      { q:`A disease reservoir refers to:`, ch:[`The vector that transmits the disease`,`The symptoms caused by the disease`,`The vaccine used to prevent a disease`,`A long-term host or environment where a pathogen naturally lives and reproduces`], ans:3, exp:`A reservoir is the natural habitat (which could be a human, animal, or environment) where a pathogen normally lives, reproduces, and from which it can potentially spread to new hosts.` },
      { q:`The incubation period of a disease refers to the time between:`, ch:[`Exposure to a pathogen and the onset of symptoms`,`Recovery and re-infection`,`Diagnosis and treatment`,`Vaccination and full immunity`], ans:0, exp:`The incubation period is the time from initial infection until symptoms first appear, during which the pathogen may be multiplying within the host, sometimes even before the person becomes contagious.` },
    ]
  },
  {
    id:'bb119', cat:'Life Sciences', title:'Vaccines & Immunity Basics', diff:'Medium',
    qs:[
      { q:`Vaccines work primarily by:`, ch:[`Directly destroying pathogens already in the body`,`Stimulating the immune system to produce a protective response (including memory cells) before actual exposure to a pathogen`,`Providing antibiotics that fight infection`,`Preventing the immune system from responding to any future infections`], ans:1, exp:`Vaccines expose the immune system to antigens (from weakened, inactivated, or partial pathogens, or via mRNA/vector platforms) so it can develop memory cells, allowing a faster, stronger response if exposed to the real pathogen later.` },
      { q:`Active immunity, gained through infection or vaccination, differs from passive immunity in that active immunity:`, ch:[`Only occurs in infants`,`Is temporary and provided by antibodies from another source`,`Involves the individual's own immune system producing antibodies and memory cells, typically providing longer-lasting protection`,`Cannot be induced by vaccines`], ans:2, exp:`Active immunity arises when the body's own immune system responds to an antigen (via infection or vaccination), producing antibodies and memory cells for longer-term protection, whereas passive immunity involves receiving pre-made antibodies from another source (like maternal antibodies) that fades over time.` },
      { q:`Memory B cells and memory T cells are important because they:`, ch:[`Directly destroy pathogens on first exposure only`,`Prevent all future infections permanently`,`Are produced only during passive immunity`,`Allow the immune system to respond more rapidly and strongly upon re-exposure to a previously encountered pathogen`], ans:3, exp:`Memory cells persist long after an initial infection or vaccination and enable a faster, stronger secondary immune response if the same pathogen is encountered again, often preventing noticeable illness.` },
      { q:`Which of these best describes an attenuated (live) vaccine?`, ch:[`Contains a weakened form of the live pathogen that can still stimulate immunity but typically doesn't cause disease in healthy people`,`Contains only inactivated toxins`,`Contains synthetic antibodies`,`Contains no biological material at all`], ans:0, exp:`Live attenuated vaccines use a weakened form of the pathogen that can still replicate and stimulate a strong, long-lasting immune response, but is generally not able to cause significant disease in individuals with healthy immune systems.` },
      { q:`Antibodies are produced by which type of immune cell?`, ch:[`T cells (cytotoxic T cells)`,`B cells (plasma cells)`,`Red blood cells`,`Platelets`], ans:1, exp:`B cells, once activated, differentiate into plasma cells that secrete large quantities of antibodies specific to the antigen that triggered the immune response.` },
      { q:`Antibodies primarily function to:`, ch:[`Regulate blood pressure`,`Directly produce ATP for immune cells`,`Bind specifically to antigens, marking pathogens for destruction or neutralizing them`,`Replace red blood cells`], ans:2, exp:`Antibodies (immunoglobulins) bind specifically to antigens on pathogens, which can neutralize the pathogen directly or mark it for destruction by other immune cells or the complement system.` },
      { q:`Which type of white blood cell directly destroys virus-infected or cancerous cells?`, ch:[`Red blood cells`,`Platelets`,`Erythrocytes`,`Cytotoxic (killer) T cells`], ans:3, exp:`Cytotoxic T cells recognize infected or abnormal cells displaying specific antigens and induce those cells to undergo programmed destruction, limiting the spread of infection.` },
      { q:`The innate immune system differs from the adaptive immune system in that innate immunity:`, ch:[`Provides a rapid, general (non-specific) first line of defense against pathogens`,`Relies exclusively on antibody production`,`Develops only after vaccination`,`Is highly specific to particular pathogens and improves with repeated exposure`], ans:0, exp:`Innate immunity provides an immediate, non-specific defense (such as skin barriers, inflammation, and phagocytic cells) present from birth, while adaptive immunity is slower to develop but highly specific and improves with repeated exposure.` },
      { q:`Herd immunity thresholds are generally higher for diseases that are:`, ch:[`Less contagious`,`More contagious (higher transmissibility)`,`Not transmissible between humans`,`Only caused by bacteria`], ans:1, exp:`Highly contagious diseases require a greater proportion of the population to be immune before transmission chains are effectively interrupted, resulting in a higher herd immunity threshold.` },
      { q:`Booster vaccine doses are sometimes needed because:`, ch:[`They convert passive immunity into active immunity`,`The original vaccine was completely ineffective`,`Immune memory and antibody levels can wane over time, so an additional dose helps restore stronger protection`,`Boosters replace the need for any prior vaccination`], ans:2, exp:`Over time, circulating antibody levels and immune memory can decline, so booster doses re-stimulate the immune system, reinforcing memory cell populations and restoring stronger, longer-lasting protection.` },
      { q:`Autoimmune disorders occur when:`, ch:[`Vaccines cause permanent infection`,`Antibodies are never produced`,`The immune system fails to respond to any pathogens`,`The immune system mistakenly attacks the body's own healthy cells and tissues`], ans:3, exp:`In autoimmune disorders, the immune system loses the ability to distinguish "self" from "non-self" and mistakenly targets the body's own healthy cells and tissues, as seen in conditions like type 1 diabetes and rheumatoid arthritis.` },
      { q:`The mRNA-based COVID-19 vaccines work by delivering genetic instructions that cause the body's own cells to:`, ch:[`Temporarily produce a harmless viral protein, triggering an immune response and memory formation`,`Directly kill the virus in the bloodstream`,`Produce antibiotics instead of antibodies`,`Permanently alter the recipient's DNA`], ans:0, exp:`mRNA vaccines deliver instructions for cells to temporarily manufacture a harmless piece of viral protein (such as a spike protein); the immune system responds to this protein and forms memory cells, without altering the recipient's own DNA.` },
    ]
  },
  {
    id:'bb120', cat:'Life Sciences', title:'Food Chains & Trophic Levels', diff:'Easy',
    qs:[
      { q:`Organisms that produce their own food through photosynthesis, forming the base of most food chains, are called:`, ch:[`Primary consumers`,`Producers`,`Decomposers`,`Secondary consumers`], ans:1, exp:`Producers (mainly plants and algae) convert sunlight into chemical energy via photosynthesis and form the foundation of virtually all food chains and webs.` },
      { q:`An organism that eats only producers (plants) is classified as a:`, ch:[`Tertiary consumer`,`Decomposer`,`Primary consumer (herbivore)`,`Secondary consumer`], ans:2, exp:`Primary consumers, or herbivores, feed directly on producers and occupy the second trophic level in a food chain.` },
      { q:`An organism that eats primary consumers (herbivores) is classified as a:`, ch:[`Decomposer`,`Primary consumer`,`Producer`,`Secondary consumer (carnivore or omnivore)`], ans:3, exp:`Secondary consumers eat primary consumers (herbivores) and occupy the third trophic level; they may be carnivores or omnivores.` },
      { q:`Decomposers, such as bacteria and fungi, play a critical ecological role by:`, ch:[`Breaking down dead organisms and waste, recycling nutrients back into the ecosystem`,`Only consuming living producers`,`Preventing energy flow through an ecosystem`,`Producing food via photosynthesis`], ans:0, exp:`Decomposers break down dead organic matter and waste products, releasing nutrients back into the soil and environment, where producers can reuse them.` },
      { q:`According to the general "10% rule" in ecology, approximately what percentage of energy is transferred from one trophic level to the next?`, ch:[`~50%`,`~10%`,`~100%`,`~90%`], ans:1, exp:`On average, only about 10% of energy stored at one trophic level is transferred to the next level as biomass; the rest is lost primarily as heat through metabolic processes.` },
      { q:`Why do food chains typically have only 4-5 trophic levels?`, ch:[`Decomposers block further energy transfer`,`There is no biological limit at all`,`Energy loss at each trophic level limits how many levels an ecosystem can support`,`Only producers can exist beyond 5 levels`], ans:2, exp:`Because a large majority of energy is lost as heat at each transfer between trophic levels, there typically isn't enough energy remaining to support many additional levels beyond the top predators.` },
      { q:`A food web differs from a simple food chain in that a food web:`, ch:[`Excludes decomposers entirely`,`Only applies to aquatic ecosystems`,`Shows only one possible path of energy flow`,`Represents multiple interconnected feeding relationships among many organisms in an ecosystem`], ans:3, exp:`A food web is a more realistic, interconnected model showing the many different feeding relationships among organisms in an ecosystem, compared to a single linear food chain.` },
      { q:`An ecological pyramid of energy is typically shaped like:`, ch:[`A pyramid narrowing from a wide base (producers) to a narrow top (top predators)`,`A perfect rectangle at every level`,`A random, unpredictable shape`,`An inverted pyramid, widest at the top`], ans:0, exp:`Energy pyramids are widest at the producer level and narrow progressively toward the top, reflecting the substantial loss of usable energy at each successive trophic level.` },
      { q:`Apex predators are organisms that:`, ch:[`Are eaten by all other organisms in the food chain`,`Have no natural predators within their ecosystem`,`Only eat producers`,`Are always the smallest organisms in an ecosystem`], ans:1, exp:`Apex predators sit at the top of the food chain/web in their ecosystem and are not typically preyed upon by other organisms.` },
      { q:`Which of the following best describes an omnivore?`, ch:[`An organism that eats only plants`,`An organism that eats only meat`,`An organism that eats both plants and animals`,`An organism that only decomposes dead matter`], ans:2, exp:`Omnivores consume both plant and animal matter, giving them dietary flexibility across multiple trophic levels.` },
      { q:`If a pesticide accumulates in higher concentrations at each successive trophic level, this phenomenon is called:`, ch:[`Decomposition`,`Symbiosis`,`Photosynthesis`,`Biomagnification`], ans:3, exp:`Biomagnification occurs when persistent toxins (like certain pesticides) become increasingly concentrated as they move up trophic levels, often reaching the highest, most harmful concentrations in apex predators.` },
      { q:`Which organism would most likely occupy the first trophic level in a typical grassland food chain?`, ch:[`Grass`,`A mouse`,`A hawk`,`A snake`], ans:0, exp:`Grass, as a photosynthetic producer, occupies the first trophic level; consumers like mice, snakes, and hawks occupy successively higher trophic levels in this example.` },
    ]
  },
  {
    id:'bb121', cat:'Life Sciences', title:'Biomes of the World', diff:'Easy',
    qs:[
      { q:`Which biome is characterized by extremely low precipitation, sparse vegetation, and organisms highly adapted to conserve water?`, ch:[`Tropical rainforest`,`Desert`,`Tundra`,`Temperate grassland`], ans:1, exp:`Deserts receive very little annual precipitation and are home to organisms with specialized adaptations for water conservation, such as succulent plants and nocturnal animals.` },
      { q:`The tropical rainforest biome is generally characterized by:`, ch:[`Long, cold winters and short summers`,`Low rainfall and low biodiversity`,`High rainfall, warm temperatures, and extremely high biodiversity`,`Permanently frozen subsoil`], ans:2, exp:`Tropical rainforests near the equator receive abundant rainfall and consistently warm temperatures year-round, supporting some of the highest levels of biodiversity of any biome on Earth.` },
      { q:`Which biome is defined by a layer of permanently frozen subsoil called permafrost?`, ch:[`Savanna`,`Chaparral`,`Tropical rainforest`,`Tundra`], ans:3, exp:`The tundra biome, found in Arctic and high-alpine regions, is characterized by extremely cold temperatures and permafrost, which limits root growth and drainage, favoring low-growing vegetation.` },
      { q:`The taiga (boreal forest) biome is primarily dominated by:`, ch:[`Coniferous (needle-leaved) evergreen trees`,`Cacti and succulents`,`Coral reefs`,`Broadleaf deciduous trees exclusively`], ans:0, exp:`The taiga, found across northern regions of North America, Europe, and Asia, is dominated by coniferous evergreen trees like spruce, fir, and pine, adapted to long, cold winters.` },
      { q:`Grasslands with scattered trees, warm temperatures, and seasonal rainfall, home to large grazing animals, best describes the:`, ch:[`Desert`,`Savanna`,`Tundra`,`Taiga`], ans:1, exp:`Savannas are tropical grasslands with scattered trees and distinct wet and dry seasons, commonly found in parts of Africa, and support large populations of grazing herbivores.` },
      { q:`Temperate deciduous forests are characterized by trees that:`, ch:[`Cannot survive freezing temperatures`,`Are evergreen year-round`,`Shed their leaves seasonally, typically in autumn`,`Are only found in desert regions`], ans:2, exp:`Temperate deciduous forests experience four distinct seasons, and their broadleaf trees shed leaves in autumn as an adaptation to conserve water and energy during colder months.` },
      { q:`Which biome is typically dominated by drought-resistant shrubs and experiences hot, dry summers with mild, wet winters (a "Mediterranean" climate)?`, ch:[`Tundra`,`Tropical rainforest`,`Taiga`,`Chaparral`], ans:3, exp:`Chaparral biomes, found in regions like California and the Mediterranean, feature dense, drought-resistant shrubs adapted to hot, dry summers and mild, wet winters, and are prone to periodic wildfires.` },
      { q:`Coral reefs are typically found in which type of environment?`, ch:[`Warm, shallow, clear tropical marine waters`,`Freshwater lakes`,`Arctic tundra`,`Cold, deep ocean waters`], ans:0, exp:`Coral reefs thrive in warm, shallow, clear tropical and subtropical marine waters, where sufficient sunlight can reach the symbiotic algae living within coral tissues.` },
      { q:`Temperate grasslands (such as prairies and steppes) are generally characterized by:`, ch:[`Dense forest cover`,`Fertile soil, moderate rainfall, and dominance of grasses with few trees`,`Permafrost year-round`,`Extremely high annual rainfall supporting rainforest growth`], ans:1, exp:`Temperate grasslands have fertile soils and moderate seasonal rainfall, generally too low to support many trees but ideal for grasses, and are often converted to agricultural land.` },
      { q:`Biome distribution across the globe is primarily determined by which two factors?`, ch:[`Distance from the equator only`,`Ocean currents and tides only`,`Temperature and precipitation patterns`,`Human population density`], ans:2, exp:`The characteristic vegetation and animal life of a biome are largely shaped by regional climate patterns, particularly average temperature and amount/seasonality of precipitation.` },
      { q:`Wetlands are ecologically important primarily because they:`, ch:[`Only exist in deserts`,`Cannot support any plant life`,`Have no biodiversity`,`Filter pollutants, reduce flooding, and provide habitat for diverse species`], ans:3, exp:`Wetlands provide critical ecosystem services, including water filtration, flood control, and habitat for a wide variety of aquatic and semi-aquatic species.` },
      { q:`Altitude can affect biome type similarly to which other factor?`, ch:[`Latitude (distance from the equator)`,`Time of day`,`Ocean salinity`,`Soil color`], ans:0, exp:`Increasing altitude produces climate changes (cooler temperatures) similar to increasing latitude, which is why mountain biomes can shift from forest at lower elevations to tundra-like conditions near the summit.` },
    ]
  },
  {
    id:'bb122', cat:'Life Sciences', title:'Conservation Biology & Endangered Species', diff:'Medium',
    qs:[
      { q:`A species classified as "endangered" is generally one that is:`, ch:[`Abundant and widespread`,`At high risk of extinction in the near future throughout all or a significant portion of its range`,`Already extinct`,`Newly discovered by scientists`], ans:1, exp:`Endangered species face a high risk of extinction due to factors such as habitat loss, low population numbers, or other threats, and are prioritized for conservation efforts.` },
      { q:`Habitat fragmentation refers to:`, ch:[`The migration of species to new habitats`,`The complete restoration of a habitat`,`The breaking up of large, continuous habitats into smaller, isolated patches`,`An increase in overall habitat size`], ans:2, exp:`Habitat fragmentation occurs when human activities (such as roads, agriculture, or development) divide large habitats into smaller, disconnected patches, which can isolate populations and reduce genetic diversity.` },
      { q:`Which of the following is generally considered the leading cause of species extinction today?`, ch:[`Volcanic eruptions`,`Ocean currents`,`Natural disasters`,`Habitat destruction and loss due to human activity`], ans:3, exp:`Habitat destruction, driven largely by human activities like deforestation, urbanization, and agriculture, is widely recognized as the primary driver of biodiversity loss and species extinction today.` },
      { q:`An invasive species is best described as a species that:`, ch:[`Is introduced to a new environment (often by humans) and causes ecological or economic harm`,`Cannot survive outside its native range`,`Always goes extinct quickly after introduction`,`Is native to an ecosystem and beneficial`], ans:0, exp:`Invasive species are typically non-native organisms introduced to a new ecosystem where they lack natural predators or controls, often outcompeting native species and disrupting the ecosystem.` },
      { q:`A keystone species is one that:`, ch:[`Only exists in captivity`,`Has a disproportionately large effect on its ecosystem relative to its abundance`,`Is the most abundant species in an ecosystem`,`Has no significant ecological role`], ans:1, exp:`Keystone species exert an outsized influence on their ecosystem's structure and function relative to their numbers; their removal can cause dramatic, cascading changes throughout the ecosystem.` },
      { q:`Captive breeding programs are a conservation strategy primarily used to:`, ch:[`Reduce genetic diversity of a species`,`Permanently remove species from the wild`,`Increase population numbers of endangered species in controlled settings, sometimes for eventual reintroduction to the wild`,`Introduce invasive species to new habitats`], ans:2, exp:`Captive breeding programs aim to increase the population of critically endangered species under controlled, protected conditions, sometimes with the goal of eventually reintroducing individuals into suitable wild habitats.` },
      { q:`Genetic diversity within a species is important for conservation because it:`, ch:[`Always leads to extinction`,`Only matters for domesticated species`,`Has no effect on a population's ability to survive change`,`Increases a population's resilience and ability to adapt to environmental changes or diseases`], ans:3, exp:`Greater genetic diversity gives a population more variation to draw on, increasing the likelihood that some individuals possess traits allowing survival in the face of new diseases, climate shifts, or other environmental pressures.` },
      { q:`Protected areas, such as national parks and wildlife reserves, primarily aim to:`, ch:[`Preserve natural habitats and reduce human-caused threats to biodiversity within their boundaries`,`Increase invasive species populations`,`Eliminate all human activity from the planet`,`Encourage habitat destruction`], ans:0, exp:`Protected areas set aside land or water to conserve natural ecosystems and species, limiting harmful human activities like unregulated development, hunting, or resource extraction within their boundaries.` },
      { q:`The term "biodiversity hotspot" refers to a region that:`, ch:[`Has very low species diversity`,`Contains an especially high number of species (often endemic ones) and faces significant habitat loss`,`Is completely free from human impact`,`Only refers to marine ecosystems`], ans:1, exp:`Biodiversity hotspots are regions with exceptionally high concentrations of endemic species that are also under serious threat from habitat destruction, making them conservation priorities.` },
      { q:`Overharvesting (overhunting or overfishing) can lead to species decline primarily because:`, ch:[`It has no effect on population size`,`It increases the reproduction rate of a species`,`Organisms are removed from a population faster than the population can naturally replace them`,`It always increases genetic diversity`], ans:2, exp:`When a species is harvested faster than it can reproduce and replenish its numbers, population size declines over time, which can eventually threaten the species with extinction if unmanaged.` },
      { q:`Climate change threatens biodiversity in part by:`, ch:[`Eliminating the need for species adaptation`,`Only affecting plant species`,`Keeping all habitats perfectly stable`,`Shifting temperature and precipitation patterns faster than many species can adapt or migrate`], ans:3, exp:`Rapid changes in temperature and precipitation patterns associated with climate change can outpace the ability of many species to adapt, migrate, or shift their ranges, increasing extinction risk.` },
      { q:`Corridors connecting fragmented habitat patches are a conservation strategy primarily meant to:`, ch:[`Allow animals to move between habitat patches, promoting gene flow and reducing the negative effects of fragmentation`,`Increase the spread of invasive species`,`Eliminate the need for protected areas`,`Permanently separate isolated populations`], ans:0, exp:`Habitat corridors reconnect fragmented patches of habitat, allowing animals to move between them, which helps maintain gene flow, supports genetic diversity, and reduces the isolation effects of fragmentation.` },
    ]
  },
  {
    id:'bb123', cat:'Life Sciences', title:'Dihybrid Crosses & Genetic Ratios', diff:'Medium',
    qs:[
      { q:`A dihybrid cross examines the inheritance of how many traits simultaneously?`, ch:[`One`,`Two`,`Three`,`Four`], ans:1, exp:`A dihybrid cross tracks the inheritance patterns of two different traits (genes) at the same time, as opposed to a monohybrid cross, which examines only one trait.` },
      { q:`In a classic dihybrid cross between two heterozygous parents (e.g., AaBb x AaBb), assuming independent assortment, what phenotypic ratio is expected in the offspring?`, ch:[`3:1`,`1:2:1`,`9:3:3:1`,`1:1:1:1`], ans:2, exp:`When two genes assort independently, crossing two double heterozygotes (AaBb x AaBb) produces a classic 9:3:3:1 phenotypic ratio among the offspring.` },
      { q:`The law of independent assortment states that:`, ch:[`Only dominant alleles are passed to offspring`,`Genes never separate during meiosis`,`Alleles for different genes separate together as a unit`,`Alleles for different genes (typically on different chromosomes) segregate independently of one another during gamete formation`], ans:3, exp:`Mendel's law of independent assortment states that alleles of different genes, generally located on different chromosome pairs, are distributed to gametes independently of each other during meiosis.` },
      { q:`Genes located very close together on the same chromosome tend to violate independent assortment because they are:`, ch:[`Linked, meaning they tend to be inherited together`,`Located on different chromosomes`,`Unable to undergo mutation`,`Always dominant`], ans:0, exp:`Genes that are physically close together on the same chromosome are said to be linked and tend to be inherited together more often than predicted by independent assortment, unless separated by crossing over.` },
      { q:`In a dihybrid cross, how many different types of gametes can a fully heterozygous individual (AaBb) produce, assuming independent assortment?`, ch:[`2`,`4`,`8`,`1`], ans:1, exp:`An AaBb individual can produce four different gamete combinations: AB, Ab, aB, and ab, each in equal proportion under independent assortment.` },
      { q:`A Punnett square for a dihybrid cross (AaBb x AaBb) contains how many total boxes/squares?`, ch:[`4`,`9`,`16`,`8`], ans:2, exp:`Since each parent produces 4 possible gamete types, a dihybrid cross Punnett square has 4 x 4 = 16 total boxes representing all possible offspring genotype combinations.` },
      { q:`If two genes are on completely different chromosomes, they are inherited:`, ch:[`Only through maternal inheritance`,`Only through paternal inheritance`,`Together as a linked unit`,`Independently of each other`], ans:3, exp:`Genes located on different chromosomes assort independently during meiosis because homologous chromosome pairs separate independently of one another.` },
      { q:`A test cross involving two traits (dihybrid test cross) crosses an individual of unknown genotype with an individual that is:`, ch:[`Homozygous recessive for both traits`,`Of unknown genotype as well`,`Heterozygous for both traits`,`Homozygous dominant for both traits`], ans:0, exp:`A test cross crosses the unknown individual with a homozygous recessive individual, since recessive alleles will only be masked if the unknown parent contributes a dominant allele, revealing the unknown genotype from the offspring ratios.` },
      { q:`If a dihybrid test cross (AaBb x aabb) is performed, what phenotypic ratio would be expected among offspring assuming independent assortment?`, ch:[`9:3:3:1`,`1:1:1:1`,`3:1`,`1:2:1`], ans:1, exp:`Crossing a double heterozygote with a double homozygous recessive individual produces four phenotypic classes in a 1:1:1:1 ratio, directly reflecting the four gamete types from the heterozygous parent.` },
      { q:`Which of the following would most likely disrupt the expected 9:3:3:1 ratio in a dihybrid cross?`, ch:[`Both genes having simple dominant/recessive inheritance`,`Complete independent assortment of the two genes`,`Genetic linkage between the two genes`,`Both genes being located on different chromosomes`], ans:2, exp:`If the two genes being studied are linked (located close together on the same chromosome), they will not assort independently, causing deviations from the expected 9:3:3:1 ratio.` },
      { q:`Crossing over during meiosis I contributes to genetic variation by:`, ch:[`Duplicating the entire genome`,`Eliminating recessive alleles`,`Preventing any exchange of genetic material`,`Exchanging segments of DNA between homologous chromosomes, creating new allele combinations`], ans:3, exp:`During crossing over, homologous chromosomes exchange corresponding segments of DNA, creating new combinations of alleles on each chromosome and increasing genetic diversity among gametes.` },
      { q:`Two genes for unrelated traits, each with simple dominant/recessive inheritance and located on different chromosomes, are crossed in parents AABB x aabb. What is the genotype of all F1 offspring?`, ch:[`AaBb`,`AABB`,`aabb`,`AaBB`], ans:0, exp:`Each parent can only contribute one type of gamete (AB from AABB, ab from aabb), so all F1 offspring will be heterozygous for both genes: AaBb.` },
    ]
  },
  {
    id:'bb124', cat:'Life Sciences', title:'Pedigree Analysis', diff:'Medium',
    qs:[
      { q:`In a standard pedigree chart, a filled-in (shaded) square typically represents:`, ch:[`An unaffected female`,`An affected male`,`An affected female`,`An unaffected male`], ans:1, exp:`By convention, squares represent males and circles represent females; a filled/shaded shape indicates the individual is affected by the trait or condition being tracked.` },
      { q:`A horizontal line connecting a square and a circle in a pedigree typically represents:`, ch:[`An adoption`,`A sibling relationship`,`A mating/reproductive pairing`,`A twin relationship`], ans:2, exp:`A horizontal line joining a square and circle indicates a mating pair (partners), while a vertical line descending from that pair connects to their offspring.` },
      { q:`If a trait skips a generation in a pedigree (unaffected parents have an affected child), this pattern is most consistent with:`, ch:[`Y-linked inheritance`,`Mitochondrial inheritance`,`Autosomal dominant inheritance`,`Autosomal recessive inheritance`], ans:3, exp:`When two unaffected (carrier) parents have an affected child, this suggests the trait is recessive, since both parents must carry a hidden copy of the recessive allele that combined in the affected offspring.` },
      { q:`In an autosomal dominant pedigree, an affected individual generally has:`, ch:[`At least one affected parent (except in cases of new mutation)`,`No affected relatives in any generation`,`Only affected daughters`,`Both parents affected in every case`], ans:0, exp:`For autosomal dominant traits, at least one parent typically must be affected (or carry the dominant allele) to pass the trait to offspring, barring a rare new/de novo mutation.` },
      { q:`Which inheritance pattern would be indicated if a trait appears much more frequently in males than females across a pedigree, with affected fathers not passing the trait to their sons?`, ch:[`Autosomal recessive`,`X-linked recessive`,`Y-linked (holandric)`,`Autosomal dominant`], ans:1, exp:`X-linked recessive traits are more common in males (who only need one copy on their single X chromosome) and are never passed from father to son (since fathers give sons a Y chromosome, not an X), a hallmark of this inheritance pattern.` },
      { q:`Y-linked (holandric) traits are passed:`, ch:[`Only through maternal lineage`,`From mother to all children`,`From father to all sons, and never to daughters`,`Equally to sons and daughters`], ans:2, exp:`Because only males have a Y chromosome, Y-linked traits are passed exclusively from father to son, appearing in every male descendant along the direct paternal line and never in daughters.` },
      { q:`Two unaffected parents who each carry one copy of a recessive allele are referred to as:`, ch:[`Affected individuals`,`Homozygous dominant`,`Homozygous recessive`,`Carriers (heterozygous)`], ans:3, exp:`Carriers are heterozygous individuals who possess one copy of a recessive allele but do not display the associated trait/condition because the dominant allele masks it; they can still pass the recessive allele to offspring.` },
      { q:`A consanguineous mating in a pedigree, often shown by a double horizontal line, refers to a mating between:`, ch:[`Closely related individuals (such as cousins)`,`Individuals of different species`,`Individuals who are both affected only`,`Two unrelated individuals`], ans:0, exp:`Consanguineous matings involve closely related individuals (e.g., first cousins), which increases the likelihood that offspring will inherit two copies of the same rare recessive allele, raising risk for recessive genetic disorders.` },
      { q:`In a pedigree, a diamond shape is typically used to represent:`, ch:[`A carrier female`,`A miscarriage or pregnancy of unknown sex`,`An affected male`,`A twin pair`], ans:1, exp:`A diamond shape in standard pedigree notation typically indicates an individual of unknown or unspecified sex, or is sometimes used to represent a miscarriage/termination.` },
      { q:`If an X-linked recessive trait is present in a mother (she is affected), what is the probability that her son will inherit the trait?`, ch:[`25%`,`50%`,`100%`,`0%`], ans:2, exp:`An affected mother is homozygous recessive on both X chromosomes, so she will pass one X carrying the recessive allele to every son (since sons receive their only X from their mother), making the probability 100%.` },
      { q:`Pedigree analysis is a useful tool primarily for:`, ch:[`Measuring an individual's blood pressure`,`Determining an organism's exact age`,`Directly sequencing an individual's entire genome`,`Tracing the inheritance pattern of a trait through a family across generations`], ans:3, exp:`Pedigrees allow geneticists and genetic counselors to visually trace how a trait or disorder is passed through generations of a family, helping to infer likely modes of inheritance and estimate recurrence risk.` },
      { q:`If a pedigree shows that a trait appears in every generation and every affected individual has at least one affected parent, this pattern is most consistent with:`, ch:[`Autosomal dominant inheritance`,`X-linked recessive inheritance only`,`A trait with no genetic basis`,`Autosomal recessive inheritance`], ans:0, exp:`A trait appearing in every generation, with affected individuals always having an affected parent, is a hallmark pattern of autosomal dominant inheritance, since only one copy of the dominant allele is needed for expression.` },
    ]
  },
  {
    id:'bb125', cat:'Life Sciences', title:'Sex-Linked Traits & Inheritance', diff:'Medium',
    qs:[
      { q:`In humans, biological sex is typically determined by which pair of chromosomes?`, ch:[`Chromosome 21`,`The X and Y chromosomes`,`Chromosome 1`,`Mitochondrial DNA`], ans:1, exp:`Humans typically have 23 pairs of chromosomes; the 23rd pair are the sex chromosomes — XX in typical females and XY in typical males.` },
      { q:`A gene located on the X chromosome, but not present on the Y chromosome, is described as:`, ch:[`Mitochondrial`,`Autosomal`,`X-linked`,`Y-linked`], ans:2, exp:`X-linked genes are located on the X chromosome; since males have only one X chromosome, they are hemizygous for these genes and will express any allele present, dominant or recessive.` },
      { q:`Red-green color blindness, a classic example of an X-linked recessive trait, is more common in males because:`, ch:[`Females cannot carry the allele at all`,`The trait is actually Y-linked`,`Males have two X chromosomes`,`Males need only one copy of the recessive allele (on their single X) to express the trait, while females need two copies`], ans:3, exp:`Since males have only one X chromosome, a single recessive allele on that X is sufficient to cause the trait, whereas females need the recessive allele on both X chromosomes to be affected, making them more likely to be unaffected carriers.` },
      { q:`If a color-blind father (X^cY) has children with a homozygous non-carrier mother (X^CX^C), what is the expected phenotype of their daughters regarding color vision?`, ch:[`All daughters will be carriers but have normal color vision`,`Half of the daughters will be color blind`,`Daughters cannot inherit the father's X chromosome`,`All daughters will be color blind`], ans:0, exp:`Daughters receive one X from each parent — the father's X carrying the recessive color-blindness allele and the mother's X carrying the normal allele — making all daughters heterozygous carriers with normal color vision.` },
      { q:`Hemophilia, an X-linked recessive blood clotting disorder, would most likely appear in which individual?`, ch:[`Only in individuals with two X chromosomes`,`A son whose mother is a carrier`,`A daughter whose parents are both unaffected non-carriers`,`Any individual regardless of X chromosome genotype`], ans:1, exp:`A son who inherits the X chromosome carrying the recessive hemophilia allele from a carrier mother will be affected, since he has only one X chromosome and no second X to carry a normal allele that could mask the condition.` },
      { q:`Which statement about X-inactivation (Lyonization) in females is correct?`, ch:[`X-inactivation only occurs in males`,`Both X chromosomes are always fully active in every cell`,`One of the two X chromosomes in each cell is randomly inactivated early in development, forming a Barr body`,`The Y chromosome is inactivated instead`], ans:2, exp:`In each cell of a typical female embryo, one of the two X chromosomes is randomly and permanently inactivated, condensing into a Barr body; this ensures a similar overall dosage of X-linked gene products between males and females.` },
      { q:`Because males are hemizygous for X-linked genes, this means males have:`, ch:[`No X-linked genes at all`,`Three copies of each X-linked gene`,`Two copies of each X-linked gene`,`Only one copy of each X-linked gene, since they have only one X chromosome`], ans:3, exp:`Males possess only a single X chromosome (paired with a Y), so they have just one copy of each gene located on the X chromosome, meaning any allele present — dominant or recessive — will be expressed.` },
      { q:`Which of the following crosses would produce all color-blind sons if the trait is X-linked recessive?`, ch:[`Affected mother (X^cX^c) x unaffected father (X^CY)`,`Carrier mother (X^CX^c) x affected father (X^cY)`,`Carrier mother (X^CX^c) x unaffected father (X^CY)`,`Unaffected mother (X^CX^C) x affected father (X^cY)`], ans:0, exp:`If the mother is homozygous affected (X^cX^c), she can only pass an X^c allele; sons receive her X and the father's Y, so all sons will inherit X^c and be affected regardless of the father's genotype.` },
      { q:`Sex-linked inheritance patterns are important in genetics primarily because they:`, ch:[`Affect autosomes only`,`Show different inheritance probabilities and phenotypic ratios in males versus females`,`Are identical to standard autosomal inheritance patterns`,`Never differ between sons and daughters`], ans:1, exp:`Because males and females differ in their sex chromosome composition (XY vs. XX), X-linked traits often show different frequency and inheritance patterns between the sexes, unlike typical autosomal traits.` },
      { q:`A female who is heterozygous for an X-linked recessive disorder is generally referred to as a(n):`, ch:[`Unaffected non-carrier`,`Affected individual`,`Carrier`,`Homozygous recessive individual`], ans:2, exp:`A heterozygous female carries one normal and one recessive allele on her two X chromosomes; she typically does not show the disorder but can pass the recessive allele to her offspring, making her a carrier.` },
      { q:`Which of these disorders is a well-known example of X-linked recessive inheritance?`, ch:[`Huntington's disease`,`Sickle cell anemia`,`Down syndrome`,`Duchenne muscular dystrophy`], ans:3, exp:`Duchenne muscular dystrophy is caused by a mutation in a gene on the X chromosome and follows X-linked recessive inheritance, predominantly affecting males.` },
      { q:`If an unaffected, non-carrier father (X^CY) and a carrier mother (X^CX^c) for an X-linked recessive trait have children, what proportion of their daughters are expected to be carriers?`, ch:[`50%`,`100%`,`0%`,`25%`], ans:0, exp:`Daughters receive the father's X^C and one of the mother's two X alleles (X^C or X^c) with equal probability, so about half of daughters are expected to be carriers (X^CX^c) and half unaffected non-carriers (X^CX^C).` },
    ]
  },
  {
    id:'bb126', cat:'Life Sciences', title:'Genetic Mutations', diff:'Medium',
    qs:[
      { q:`A mutation is best defined as:`, ch:[`Any change in an organism's behavior`,`A change in the nucleotide sequence of an organism's DNA`,`The process of protein folding`,`The transfer of genes between species only`], ans:1, exp:`A mutation is any alteration in the sequence of nucleotides making up an organism's DNA, which can range from a single base change to large structural changes.` },
      { q:`A point mutation that changes a codon so that it codes for a different amino acid is called a:`, ch:[`Frameshift mutation`,`Silent mutation`,`Missense mutation`,`Nonsense mutation`], ans:2, exp:`A missense mutation changes a single nucleotide such that the resulting codon specifies a different amino acid, potentially altering protein structure and function.` },
      { q:`A point mutation that changes a codon into a premature stop codon is called a:`, ch:[`Insertion`,`Silent mutation`,`Missense mutation`,`Nonsense mutation`], ans:3, exp:`A nonsense mutation converts a codon that normally specifies an amino acid into a stop codon, resulting in a prematurely truncated, often non-functional protein.` },
      { q:`A mutation that changes a codon but still codes for the same amino acid (due to the redundancy of the genetic code) is called a:`, ch:[`Silent mutation`,`Frameshift mutation`,`Nonsense mutation`,`Chromosomal mutation`], ans:0, exp:`Silent mutations alter the DNA/mRNA sequence but, due to the degeneracy (redundancy) of the genetic code, still result in the same amino acid being incorporated, typically causing no change in protein function.` },
      { q:`The insertion or deletion of a number of nucleotides not divisible by three typically causes a:`, ch:[`Silent mutation`,`Frameshift mutation, altering the reading frame for all downstream codons`,`No change to the protein at all`,`Only a change to the start codon`], ans:1, exp:`Insertions or deletions not in multiples of three shift the ribosome's reading frame during translation, typically altering every subsequent codon and often producing a severely non-functional protein.` },
      { q:`Mutations that occur in gametes (sperm or egg cells) are significant because they:`, ch:[`Always cause immediate death of the organism`,`Cannot affect offspring`,`Can be passed on to offspring and appear in every cell of the resulting individual`,`Only affect the somatic cells of the parent`], ans:2, exp:`Germline mutations occurring in gametes can be transmitted to offspring, becoming present in every cell of the resulting individual and potentially passed to future generations.` },
      { q:`Somatic mutations differ from germline mutations in that somatic mutations:`, ch:[`Only occur in gametes`,`Never affect the individual in which they occur`,`Are always passed to offspring`,`Occur in non-reproductive body cells and are not passed on to offspring`], ans:3, exp:`Somatic mutations arise in non-reproductive (body) cells during an individual's lifetime; they can affect that individual (e.g., contributing to cancer) but are not passed on to the next generation.` },
      { q:`Which of the following is a common environmental agent known to increase mutation rates (a mutagen)?`, ch:[`Ultraviolet (UV) radiation`,`Table salt`,`Room-temperature air`,`Pure water`], ans:0, exp:`UV radiation can damage DNA by causing the formation of pyrimidine dimers, which, if not properly repaired, can lead to mutations; it is a well-known mutagen, particularly relevant to skin cancer risk.` },
      { q:`Chromosomal mutations, such as duplications, deletions, inversions, and translocations, differ from point mutations in that they typically:`, ch:[`Affect only a single nucleotide`,`Involve changes to large segments of a chromosome`,`Never affect phenotype`,`Only occur in bacteria`], ans:1, exp:`Chromosomal mutations involve structural changes to large segments of DNA or entire chromosomes (such as duplicating, deleting, inverting, or relocating large regions), unlike point mutations, which affect only a single or a few nucleotides.` },
      { q:`Not all mutations are harmful; some mutations can be:`, ch:[`Only found in extinct species`,`Only ever harmful, never neutral or beneficial`,`Neutral (having no significant effect) or occasionally beneficial, providing raw material for evolution`,`Impossible to occur in nature`], ans:2, exp:`Mutations vary in effect — many are neutral (no functional impact), some are harmful, and a small fraction can be beneficial, providing the genetic variation that natural selection acts upon during evolution.` },
      { q:`DNA repair mechanisms within cells primarily function to:`, ch:[`Convert all mutations into beneficial ones`,`Prevent DNA replication entirely`,`Intentionally increase the mutation rate`,`Detect and correct errors or damage in the DNA sequence, reducing the frequency of mutations`], ans:3, exp:`Cells possess various repair mechanisms (such as mismatch repair and nucleotide excision repair) that detect and fix errors or damage in DNA, substantially reducing the number of mutations that persist and get passed on.` },
      { q:`Sickle cell anemia is caused by which type of mutation in the beta-globin gene?`, ch:[`A single missense point mutation changing one amino acid`,`A nonsense mutation eliminating the entire protein`,`A silent mutation with no effect on the protein`,`A large chromosomal deletion`], ans:0, exp:`Sickle cell anemia results from a single missense point mutation in the beta-globin gene, causing one amino acid substitution (glutamic acid to valine) that alters hemoglobin's structure and behavior under low oxygen conditions.` },
    ]
  },
  {
    id:'bb127', cat:'Life Sciences', title:'Natural Selection & Adaptation', diff:'Easy',
    qs:[
      { q:`Natural selection acts primarily on:`, ch:[`Traits with no effect on survival or reproduction`,`Heritable variations that affect an organism's survival and reproductive success`,`Random, non-heritable changes only`,`Traits acquired during an organism's lifetime, like a scar`], ans:1, exp:`Natural selection favors heritable traits that improve an organism's chances of surviving and reproducing in its environment, gradually increasing the frequency of those traits in the population over generations.` },
      { q:`An adaptation is best defined as:`, ch:[`A trait that always decreases survival chances`,`Any random trait an organism has`,`A heritable trait that increases an organism's fitness in its environment`,`A trait acquired through learning`], ans:2, exp:`Adaptations are heritable traits shaped by natural selection over generations because they enhance an organism's ability to survive and reproduce in its specific environment.` },
      { q:`In evolutionary biology, "fitness" refers to an organism's:`, ch:[`Body size compared to other organisms`,`Ability to learn new behaviors`,`Physical strength or speed`,`Relative ability to survive and pass on its genes to the next generation`], ans:3, exp:`Fitness is a measure of an organism's reproductive success — how effectively it survives and passes on its genes relative to other individuals in the population — not necessarily physical strength.` },
      { q:`Which of these is a prerequisite for natural selection to occur within a population?`, ch:[`Heritable variation must exist among individuals in the population`,`The environment must never change`,`Every individual must reproduce equally`,`All individuals must be genetically identical`], ans:0, exp:`Natural selection requires heritable variation among individuals; without genetic differences that can be passed to offspring, there is nothing for selection to act upon.` },
      { q:`Camouflage that allows an organism to blend into its surroundings and avoid predators is an example of a(n):`, ch:[`Behavioral adaptation only`,`Structural (physical) adaptation`,`Learned behavior`,`Mutation with no survival benefit`], ans:1, exp:`Camouflage coloring or patterning is a structural (physical) adaptation that has evolved because it improves survival by helping an organism avoid detection by predators or prey.` },
      { q:`Directional selection occurs when:`, ch:[`Both extreme phenotypes are favored over the average`,`No phenotype is favored over any other`,`Individuals with an extreme phenotype (at one end of the range) are favored over the average and other extreme`,`Individuals with the average phenotype are favored over both extremes`], ans:2, exp:`Directional selection favors one extreme phenotype over the average and the opposite extreme, shifting the population's trait distribution in that direction over time (e.g., peppered moth coloration during industrialization).` },
      { q:`Stabilizing selection tends to:`, ch:[`Create two distinct phenotype peaks`,`Always increase genetic diversity`,`Favor extreme phenotypes over the average`,`Reduce variation by favoring the average/intermediate phenotype over both extremes`], ans:3, exp:`Stabilizing selection favors intermediate phenotypes and selects against both extremes, which reduces variation and stabilizes the trait around the average (e.g., human birth weight near an optimal average).` },
      { q:`Disruptive selection tends to:`, ch:[`Favor both extreme phenotypes over the intermediate, potentially leading to two distinct groups`,`Eliminate all variation in a trait`,`Only occur in asexual organisms`,`Favor the average phenotype`], ans:0, exp:`Disruptive selection favors individuals at both extremes of a trait's range while selecting against intermediate phenotypes, which can increase variation and potentially contribute to speciation.` },
      { q:`Antibiotic resistance evolving in bacterial populations is a well-documented real-world example of:`, ch:[`Genetic drift only`,`Natural selection acting on pre-existing variation in resistance genes`,`Artificial selection exclusively`,`A trait with no heritable basis`], ans:1, exp:`When antibiotics are applied, bacteria with pre-existing resistance mutations survive and reproduce at higher rates than susceptible bacteria, a clear real-world example of natural selection acting on heritable variation.` },
      { q:`Artificial selection differs from natural selection primarily in that artificial selection:`, ch:[`Only applies to plants, never animals`,`Occurs only in nature without human input`,`Involves humans intentionally choosing which organisms reproduce based on desired traits`,`Cannot produce noticeable changes in a species`], ans:2, exp:`Artificial selection (selective breeding) involves humans deliberately choosing which individuals reproduce based on desirable traits (e.g., in dog breeds or crop varieties), whereas natural selection is driven by the environment rather than human choice.` },
      { q:`Convergent evolution refers to the phenomenon where:`, ch:[`A single species stops evolving entirely`,`Two species merge into one`,`Closely related species diverge to look very different`,`Unrelated species independently evolve similar traits due to similar environmental pressures`], ans:3, exp:`Convergent evolution occurs when unrelated species independently evolve analogous structures or traits (such as the wings of insects, birds, and bats) in response to similar environmental challenges, despite not sharing a recent common ancestor for that trait.` },
      { q:`A vestigial structure, such as the human appendix or whale pelvic bones, is best understood as:`, ch:[`A remnant structure that had a function in an ancestral species but has reduced or lost function in the current species`,`Evidence against evolution`,`A structure found only in extinct species`,`A brand-new structure with a critical current function`], ans:0, exp:`Vestigial structures are remnants of features that served important functions in ancestral species but have become reduced, non-functional, or repurposed over evolutionary time in descendant species.` },
    ]
  },
  {
    id:'bb128', cat:'Life Sciences', title:'Speciation', diff:'Medium',
    qs:[
      { q:`Speciation is best defined as the process by which:`, ch:[`A single species goes extinct`,`One species splits into two or more distinct species over time`,`Two species merge into one`,`An individual organism changes species during its lifetime`], ans:1, exp:`Speciation is the evolutionary process through which populations of a single ancestral species diverge over time to become two or more distinct species.` },
      { q:`The biological species concept defines a species primarily based on:`, ch:[`DNA sequence identity of 100%`,`Physical appearance alone`,`The ability of members to interbreed and produce viable, fertile offspring`,`Geographic location only`], ans:2, exp:`Under the biological species concept, a species is defined as a group of organisms that can interbreed in nature and produce viable, fertile offspring, while being reproductively isolated from other such groups.` },
      { q:`Allopatric speciation occurs when populations become reproductively isolated primarily due to:`, ch:[`Chromosomal changes without any separation`,`Identical environments`,`Differences in mating behavior within the same location`,`A physical/geographic barrier separating populations`], ans:3, exp:`Allopatric speciation occurs when a geographic barrier (such as a mountain range, river, or ocean) physically separates populations, preventing gene flow and allowing them to diverge independently over time.` },
      { q:`Sympatric speciation occurs when new species form:`, ch:[`Within the same geographic location, without physical separation`,`Exclusively through hybridization with another species`,`Only in asexually reproducing organisms`,`Only after complete geographic separation`], ans:0, exp:`Sympatric speciation occurs without geographic isolation; reproductive isolation instead arises through mechanisms like polyploidy, habitat/niche differentiation, or behavioral changes within the same area.` },
      { q:`Prezygotic reproductive isolating mechanisms prevent:`, ch:[`Migration between populations`,`Fertilization or mating from occurring between different species in the first place`,`Offspring survival after fertilization only`,`Any genetic mutation`], ans:1, exp:`Prezygotic barriers act before fertilization can occur, such as differences in mating behavior, timing, or physical incompatibility, preventing successful mating between different species.` },
      { q:`Postzygotic reproductive isolating mechanisms act by:`, ch:[`Occurring only before fertilization`,`Preventing mating from occurring at all`,`Reducing the viability or fertility of hybrid offspring after fertilization has occurred`,`Preventing any physical contact between species`], ans:2, exp:`Postzygotic barriers occur after fertilization, resulting in hybrid offspring that may be inviable, weak, sterile (such as the mule), or otherwise less fit, limiting successful gene flow between the parent species.` },
      { q:`Which of the following is an example of a prezygotic isolating mechanism based on differing reproductive timing?`, ch:[`Hybrid inviability`,`Reduced hybrid fitness`,`Hybrid sterility`,`Temporal (seasonal) isolation, where species breed at different times`], ans:3, exp:`Temporal isolation is a prezygotic mechanism in which species that could otherwise interbreed are kept separate because they breed during different seasons or times of day.` },
      { q:`Adaptive radiation refers to:`, ch:[`The relatively rapid diversification of a single ancestral species into many new species, often filling different ecological niches`,`A decrease in genetic diversity over time`,`Two species merging into a hybrid`,`The extinction of a single species`], ans:0, exp:`Adaptive radiation occurs when a single ancestral species rapidly diversifies into many descendant species, often after colonizing a new environment with diverse available niches, as seen in Darwin's finches on the Galápagos Islands.` },
      { q:`A ring species is a phenomenon in which:`, ch:[`Two identical species merge into one`,`Populations connected in a geographic ring can interbreed with neighbors, but the two ends of the ring cannot interbreed with each other`,`Only one population exists in a circular habitat`,`Species reproduce exclusively asexually`], ans:1, exp:`In a ring species, neighboring populations along a geographic ring can successfully interbreed, but as you move around the ring, accumulated differences mean that populations at the two ends, when they meet, can no longer interbreed — illustrating speciation as a gradual process.` },
      { q:`Reproductive isolation is significant in speciation because it:`, ch:[`Only matters for asexual organisms`,`Increases gene flow between diverging populations`,`Prevents gene flow between populations, allowing them to accumulate genetic differences independently`,`Has no impact on genetic divergence`], ans:2, exp:`Reproductive isolation stops or limits gene flow between populations, which is essential for allowing each population to accumulate independent genetic changes and eventually diverge into separate species.` },
      { q:`Polyploidy, an increase in the number of complete chromosome sets, is a mechanism especially important for speciation in:`, ch:[`Reptiles exclusively`,`Bacteria only`,`Most mammal species`,`Plants`], ans:3, exp:`Polyploidy (having extra complete sets of chromosomes) is relatively common and can rapidly create sympatric speciation events in plants, since polyploid individuals often cannot successfully interbreed with the original diploid population.` },
      { q:`Two populations of the same ancestral species living in different, non-overlapping habitats begin to develop non-interbreeding status. This scenario best describes:`, ch:[`The process of speciation resulting from reduced gene flow between the populations`,`Genetic drift with no divergence`,`Vestigial structure formation`,`Convergent evolution`], ans:0, exp:`When gene flow between two geographically or ecologically separated populations is reduced or eliminated, the populations can accumulate independent genetic differences over time, potentially leading to full speciation.` },
    ]
  },
  {
    id:'bb129', cat:'Life Sciences', title:'Evidence for Evolution', diff:'Medium',
    qs:[
      { q:`Homologous structures, such as the forelimbs of humans, whales, and bats, provide evidence for evolution because they:`, ch:[`Have completely different underlying bone structures despite similar appearance`,`Share a similar underlying skeletal structure inherited from a common ancestor, despite differing functions`,`Prove that all species are identical`,`Only appear in unrelated species`], ans:1, exp:`Homologous structures share a common underlying anatomical/skeletal pattern inherited from a shared ancestor, even though the structures may have been modified over time to serve different functions (e.g., grasping, swimming, flying).` },
      { q:`Analogous structures, such as the wings of insects and birds, differ from homologous structures in that analogous structures:`, ch:[`Are never found in nature`,`Arise from a shared common ancestor with the same structure`,`Have similar function but arose independently in unrelated lineages (convergent evolution), not from shared ancestry`,`Prove direct common ancestry for that specific structure`], ans:2, exp:`Analogous structures perform similar functions but evolved independently in different lineages facing similar environmental pressures (convergent evolution), rather than being inherited from a shared common ancestor.` },
      { q:`The fossil record provides evidence for evolution primarily by showing:`, ch:[`Only modern species, with no record of extinct organisms`,`That species never go extinct`,`That all species appeared simultaneously with no change over time`,`A chronological progression of changes in organisms' structures over geological time`], ans:3, exp:`The fossil record documents changes in organisms' forms across geological time, showing transitional forms and a general progression consistent with gradual evolutionary change and common descent.` },
      { q:`Comparing DNA sequences between species is a modern method used to provide evidence for evolution by revealing:`, ch:[`Degrees of genetic similarity that generally correlate with how closely related species are`,`That DNA has no relationship to evolutionary history`,`That mutations never occur`,`That unrelated species always have identical DNA`], ans:0, exp:`Species that are more closely related (based on other lines of evidence) typically show greater similarity in their DNA sequences, and the degree of genetic difference can be used to estimate evolutionary relationships and divergence times.` },
      { q:`Vestigial structures, like the human tailbone (coccyx), support evolution by evidence that:`, ch:[`These structures were newly created for modern humans`,`These structures are remnants of functional structures present in ancestral species`,`Humans evolved independently of other primates`,`Vestigial structures always retain their original full function`], ans:1, exp:`Vestigial structures like the human coccyx (remnant of an ancestral tail) suggest common ancestry with organisms in which that structure had a functional role, providing evidence of evolutionary history.` },
      { q:`Comparative embryology provides evidence for evolution by showing that:`, ch:[`Embryonic development is unrelated to genetics`,`Embryos of different vertebrate species look completely different from the earliest stages`,`Embryos of many vertebrate species show striking similarities in early developmental stages, suggesting shared ancestry`,`All species develop identically throughout their entire lifespan`], ans:2, exp:`Early embryos of many vertebrate species (fish, birds, mammals) show notable similarities, such as pharyngeal (gill) slits, reflecting shared developmental genetic pathways inherited from a common ancestor.` },
      { q:`Biogeography, the study of species' geographic distribution, supports evolution by observations such as:`, ch:[`All continents having identical species`,`Species distribution having no connection to historical continental movements`,`Species being randomly distributed with no relation to geography or ancestry`,`Species being more similar to nearby species than to species in similar environments on other continents`], ans:3, exp:`Species on a given continent often more closely resemble other species on that same continent (even in different habitats) than they resemble species in similar habitats elsewhere, a pattern best explained by shared regional ancestry and evolutionary history.` },
      { q:`Antibiotic resistance in bacteria observed within a human lifetime provides evidence that:`, ch:[`Evolutionary change (natural selection) can be observed occurring in real time in living populations`,`Bacteria never change over time`,`Only fossils can provide evidence of evolution`,`Evolution cannot be observed directly`], ans:0, exp:`The rapid evolution of antibiotic-resistant bacteria demonstrates that natural selection and evolutionary change can be directly observed occurring within short, even human-lifetime, timescales.` },
      { q:`A transitional fossil, such as Tiktaalik (showing features intermediate between fish and early tetrapods), is significant because it:`, ch:[`Shows no relationship between different groups of organisms`,`Displays a mix of features from two different groups, supporting a gradual evolutionary transition between them`,`Proves that fish and tetrapods appeared simultaneously with no connection`,`Is unrelated to the fossil record`], ans:1, exp:`Transitional fossils like Tiktaalik show a combination of ancestral and derived traits (e.g., fins with wrist-like bones), providing strong evidence for gradual evolutionary transitions between major groups of organisms.` },
      { q:`Pseudogenes (non-functional remnants of once-functional genes) found in an organism's genome provide evidence for evolution because they:`, ch:[`Are found only in bacteria`,`Actively code for essential new proteins`,`Suggest the organism's ancestors once had a functional version of that gene, now inactivated by mutations`,`Prove that genomes never accumulate mutations`], ans:2, exp:`Pseudogenes are remnants of genes that have accumulated mutations rendering them non-functional; their presence, especially when shared with related species at similar genomic locations, provides strong evidence of shared evolutionary ancestry.` },
      { q:`Which of the following best summarizes how multiple independent lines of evidence (fossils, anatomy, embryology, DNA, biogeography) support evolutionary theory?`, ch:[`Only DNA evidence is considered valid`,`They are unrelated fields with no bearing on each other`,`Each line of evidence contradicts the others`,`They independently converge on and reinforce a consistent picture of common descent and change over time`], ans:3, exp:`The strength of evolutionary theory comes largely from the convergence of independent lines of evidence — anatomy, fossils, embryology, molecular biology, and biogeography — which all consistently point toward common descent and gradual change over time.` },
      { q:`The distribution of marsupial mammals being heavily concentrated in Australia, an isolated continent, is best explained as evidence from the field of:`, ch:[`Biogeography`,`Molecular genetics`,`Direct observation of natural selection`,`Comparative embryology`], ans:0, exp:`Biogeography examines the geographic distribution of species; Australia's long isolation from other continents allowed its marsupial populations to diversify largely independently, explaining their concentration there rather than elsewhere.` },
    ]
  },
  {
    id:'bb130', cat:'Life Sciences', title:'The Cell Cycle & Checkpoints', diff:'Medium',
    qs:[
      { q:`The cell cycle is generally divided into which two main phases?`, ch:[`Prophase and metaphase`,`Interphase and the mitotic (M) phase`,`G1 and G2 only`,`Meiosis I and meiosis II`], ans:1, exp:`The cell cycle consists of interphase (during which the cell grows and replicates its DNA) followed by the mitotic (M) phase, during which the cell divides its nucleus and cytoplasm.` },
      { q:`During which phase of interphase does DNA replication occur?`, ch:[`M phase`,`G1 phase`,`S phase`,`G2 phase`], ans:2, exp:`S phase ("synthesis" phase) is when the cell replicates its entire genome, doubling its DNA content in preparation for cell division.` },
      { q:`Which phase of interphase occurs immediately before DNA replication, during which the cell grows and carries out normal functions?`, ch:[`S phase`,`G2 phase`,`Cytokinesis`,`G1 phase`], ans:3, exp:`G1 phase is the first gap phase, during which the cell grows in size, produces necessary proteins/organelles, and carries out normal cellular functions before DNA replication begins.` },
      { q:`Cells that have temporarily or permanently exited the cell cycle and stopped dividing are said to be in:`, ch:[`G0 phase`,`Anaphase`,`S phase`,`G2 phase`], ans:0, exp:`G0 is a resting or quiescent phase outside the active cell cycle; cells such as mature neurons often remain in G0 indefinitely, while others (e.g., liver cells) can re-enter the cycle when needed.` },
      { q:`The G1 checkpoint (restriction point) primarily checks for:`, ch:[`Correct chromosome alignment during metaphase`,`Adequate cell size, nutrients, and absence of DNA damage before committing to division`,`Complete separation of sister chromatids`,`Cytoplasmic division`], ans:1, exp:`The G1 checkpoint assesses whether the cell has sufficient size, resources, and undamaged DNA before allowing progression into S phase; if conditions aren't met, the cell cycle can pause or the cell may enter G0.` },
      { q:`The G2 checkpoint primarily verifies that:`, ch:[`The cell has completed cytokinesis`,`The cell is large enough to begin the cycle`,`DNA replication has been completed accurately and without damage before entering mitosis`,`Sister chromatids have separated`], ans:2, exp:`The G2 checkpoint ensures DNA replication is complete and checks for DNA damage before allowing the cell to proceed into mitosis, helping prevent division with an incompletely or incorrectly replicated genome.` },
      { q:`The M (spindle/metaphase) checkpoint primarily ensures that:`, ch:[`DNA replication has started`,`The cell has grown to the correct size`,`Cytokinesis has already occurred`,`All chromosomes are properly attached to spindle fibers and aligned before anaphase begins`], ans:3, exp:`The spindle checkpoint (metaphase checkpoint) verifies that all chromosomes are correctly attached to spindle fibers from opposite poles and properly aligned before allowing the cell to proceed into anaphase, preventing errors in chromosome segregation.` },
      { q:`Cyclins and cyclin-dependent kinases (CDKs) function together to:`, ch:[`Regulate progression through the cell cycle by phosphorylating target proteins at specific checkpoints`,`Break down the nuclear envelope permanently`,`Only function during meiosis`,`Directly synthesize new DNA nucleotides`], ans:0, exp:`Cyclins bind to and activate CDKs; the resulting cyclin-CDK complexes phosphorylate various target proteins to drive the cell through checkpoints and into the next phase of the cell cycle.` },
      { q:`A tumor suppressor gene, such as p53, functions to:`, ch:[`Promote uncontrolled cell division`,`Halt the cell cycle or trigger apoptosis in cells with significant DNA damage`,`Directly cause cancer`,`Prevent DNA replication entirely under normal conditions`], ans:1, exp:`p53 is a key tumor suppressor that detects DNA damage and can halt the cell cycle to allow repair, or trigger programmed cell death (apoptosis) if damage is too severe, helping prevent damaged cells from proliferating.` },
      { q:`Cancer can result when cell cycle regulation fails, often due to:`, ch:[`Excessive apoptosis`,`Complete cessation of all cell division`,`Mutations that inactivate tumor suppressor genes or overactivate genes promoting cell division (oncogenes)`,`Cells becoming too large`], ans:2, exp:`Cancer often arises from an accumulation of mutations that inactivate tumor suppressor genes (which normally restrain the cycle) and/or activate oncogenes (which normally promote division), leading to uncontrolled cell proliferation.` },
      { q:`Cytokinesis refers to the process of:`, ch:[`Alignment of chromosomes at the cell's equator`,`Formation of the mitotic spindle`,`DNA replication`,`Division of the cytoplasm, resulting in two separate daughter cells`], ans:3, exp:`Cytokinesis is the final physical division of the cytoplasm following mitosis (or meiosis), producing two separate daughter cells, each with its own nucleus and set of organelles.` },
      { q:`Cells that divide uncontrollably due to a bypassed cell cycle checkpoint most directly risk becoming:`, ch:[`Cancerous, forming a tumor from unchecked proliferation`,`Permanently stuck in G0`,`Unable to complete any part of the cell cycle`,`More efficient at normal tissue repair`], ans:0, exp:`When checkpoint controls fail to halt division of a damaged or abnormal cell, that cell can proliferate uncontrollably, potentially forming a tumor — the basis of much cancer development.` },
    ]
  },
  {
    id:'bb131', cat:'Life Sciences', title:'Osmosis & Diffusion', diff:'Easy',
    qs:[
      { q:`Diffusion is best defined as the movement of particles from:`, ch:[`An area of low concentration to an area of high concentration`,`An area of high concentration to an area of low concentration, until equilibrium is reached`,`Inside a cell to outside only`,`Outside a cell to inside only`], ans:1, exp:`Diffusion is the net movement of particles from a region of higher concentration to a region of lower concentration, driven by random molecular motion, until concentrations become equal (equilibrium).` },
      { q:`Osmosis specifically refers to the diffusion of:`, ch:[`Gases only`,`Any solute across a membrane`,`Water across a selectively permeable membrane`,`Proteins across a membrane`], ans:2, exp:`Osmosis is a special case of diffusion involving the net movement of water molecules across a selectively permeable membrane from an area of lower solute concentration to an area of higher solute concentration.` },
      { q:`A solution with a lower solute concentration relative to another solution is described as:`, ch:[`Isotonic`,`Saturated`,`Hypertonic`,`Hypotonic`], ans:3, exp:`A hypotonic solution has a lower concentration of solutes (and thus a higher concentration of water) relative to another solution being compared.` },
      { q:`If a red blood cell is placed in a hypertonic solution, water will generally:`, ch:[`Move out of the cell, causing it to shrink (crenate)`,`Remain completely unchanged`,`Move in both directions equally with no net effect`,`Move into the cell, causing it to swell and potentially burst`], ans:0, exp:`In a hypertonic solution, the surrounding environment has a higher solute concentration than inside the cell, so water moves out of the cell by osmosis, causing the cell to shrink (crenation).` },
      { q:`If a red blood cell is placed in a hypotonic solution, water will generally:`, ch:[`Move out of the cell`,`Move into the cell, potentially causing it to swell and lyse (burst)`,`Not move at all`,`Immediately evaporate`], ans:1, exp:`In a hypotonic solution, the surrounding environment has a lower solute concentration than inside the cell, so water moves into the cell by osmosis, which can cause the cell to swell and potentially burst (lyse).` },
      { q:`An isotonic solution is one in which:`, ch:[`Solute concentration is much higher outside the cell than inside`,`Solute concentration is much lower outside the cell than inside`,`Solute concentration is equal inside and outside the cell, resulting in no net water movement`,`No water is present at all`], ans:2, exp:`In an isotonic solution, solute concentrations are equal on both sides of the membrane, so there is no net movement of water into or out of the cell, and cell volume remains stable.` },
      { q:`Facilitated diffusion differs from simple diffusion in that facilitated diffusion:`, ch:[`Moves substances against their concentration gradient`,`Only occurs in plant cells`,`Requires ATP energy input`,`Requires a specific membrane transport protein to move substances across the membrane`], ans:3, exp:`Facilitated diffusion still moves substances down their concentration gradient (no ATP required) but requires specific channel or carrier proteins to help larger or charged molecules cross the membrane.` },
      { q:`Active transport differs fundamentally from diffusion and osmosis in that active transport:`, ch:[`Requires energy (typically ATP) to move substances against their concentration gradient`,`Never requires a membrane protein`,`Only occurs in prokaryotic cells`,`Moves substances down their concentration gradient without energy`], ans:0, exp:`Unlike passive diffusion and osmosis, active transport requires an input of cellular energy (usually from ATP) to move substances against their concentration gradient, from low to high concentration.` },
      { q:`Turgor pressure in plant cells, important for maintaining rigidity, results from:`, ch:[`Water leaving the central vacuole under hypertonic conditions`,`Water entering the central vacuole, pushing the cell membrane against the rigid cell wall`,`The complete absence of water in the cell`,`Active transport of glucose only`], ans:1, exp:`When placed in a hypotonic or isotonic environment, water enters plant cells and fills the central vacuole, creating turgor pressure that pushes the cell membrane firmly against the rigid cell wall, keeping the plant rigid and upright.` },
      { q:`Plasmolysis in plant cells occurs when the cell is placed in a __ solution, causing the cell membrane to pull away from the cell wall.`, ch:[`Hypotonic`,`Isotonic`,`Hypertonic`,`Neutral`], ans:2, exp:`In a hypertonic solution, water leaves the plant cell by osmosis, causing the cell membrane and cytoplasm to shrink away from the rigid cell wall — a process called plasmolysis, which can cause wilting.` },
      { q:`Factors that generally increase the rate of diffusion include:`, ch:[`A concentration gradient of zero`,`Increasing the distance particles must travel`,`Larger particle size and lower temperature`,`Higher temperature, smaller particle size, and a steeper concentration gradient`], ans:3, exp:`Diffusion rate increases with higher temperature (more kinetic energy), smaller particle size, shorter diffusion distance, and a steeper (larger) concentration gradient.` },
      { q:`Why is osmosis particularly important for maintaining homeostasis in living cells?`, ch:[`Because improper water balance can cause cells to shrink, swell, or burst, disrupting normal cell function`,`Because it only affects dead cells`,`Because it prevents all molecular movement across membranes`,`It has no real biological significance`], ans:0, exp:`Cells must carefully regulate water balance via osmosis; excessive water loss or gain can disrupt cell volume, structural integrity, and metabolic function, making osmoregulation essential for maintaining homeostasis.` },
    ]
  },
  {
    id:'bb132', cat:'Life Sciences', title:'Homeostasis & Feedback Loops', diff:'Easy',
    qs:[
      { q:`Homeostasis is best defined as the body's ability to:`, ch:[`Constantly change its internal environment randomly`,`Maintain a relatively stable internal environment despite external changes`,`Grow indefinitely without limits`,`Eliminate all internal regulation`], ans:1, exp:`Homeostasis refers to the physiological processes that maintain a stable, balanced internal environment (such as temperature, pH, and glucose levels) despite fluctuations in the external environment.` },
      { q:`In a negative feedback loop, the response to a change in the system generally:`, ch:[`Only occurs once and never repeats`,`Amplifies the original change further away from the set point`,`Counteracts the original change, returning the system toward its set point`,`Has no relationship to the original stimulus`], ans:2, exp:`Negative feedback loops work to counteract or reverse a deviation from a set point, bringing the system's variable back toward its normal, stable range — the predominant mechanism for maintaining homeostasis.` },
      { q:`Regulation of human body temperature through sweating and shivering is a classic example of:`, ch:[`No feedback mechanism at all`,`Passive diffusion only`,`Positive feedback`,`Negative feedback`], ans:3, exp:`Body temperature regulation is a textbook example of negative feedback: when temperature rises above the set point, sweating cools the body down; when it drops too low, shivering generates heat to warm it back up.` },
      { q:`In a positive feedback loop, the response to a change:`, ch:[`Amplifies or intensifies the initial change, moving further away from the original state`,`Has no effect on the system`,`Always maintains stable homeostasis`,`Counteracts and reverses the initial change`], ans:0, exp:`Positive feedback loops amplify the original stimulus rather than reversing it, pushing the system further in the same direction, and are typically used for processes that need a rapid, decisive endpoint rather than for maintaining stability.` },
      { q:`Which of the following is a physiological example of a positive feedback loop?`, ch:[`Blood glucose regulation by insulin and glucagon`,`Uterine contractions during childbirth, intensified by oxytocin release`,`Body temperature regulation`,`Blood pH buffering`], ans:1, exp:`During childbirth, uterine contractions stimulate oxytocin release, which increases contraction intensity, further stimulating oxytocin release — an amplifying positive feedback loop that continues until the baby is delivered.` },
      { q:`In blood glucose regulation, when blood glucose rises after a meal, the pancreas releases:`, ch:[`Growth hormone only`,`Glucagon, to raise blood glucose further`,`Insulin, to lower blood glucose by promoting cellular uptake and storage`,`Adrenaline exclusively`], ans:2, exp:`When blood glucose rises, the pancreas releases insulin, which promotes glucose uptake by cells and storage as glycogen, lowering blood glucose back toward the normal set point — a classic negative feedback response.` },
      { q:`A "set point" in a homeostatic system refers to:`, ch:[`A random fluctuating value with no target`,`The point at which the system permanently shuts down`,`The maximum possible value a variable can reach`,`The target/normal value that the regulatory system works to maintain`], ans:3, exp:`The set point is the normal or target value (such as ~98.6°F for human body temperature) that homeostatic mechanisms work to maintain through corrective feedback responses.` },
      { q:`Sensors (receptors) in a homeostatic feedback loop primarily function to:`, ch:[`Detect changes or deviations from the set point and relay that information to a control center`,`Store excess nutrients`,`Only function during positive feedback`,`Directly cause the corrective response without detecting anything`], ans:0, exp:`Sensors/receptors detect changes in a monitored variable (like temperature or blood pressure) and send that information to a control center (often part of the brain), which then coordinates an appropriate corrective response via effectors.` },
      { q:`In a homeostatic feedback loop, "effectors" are structures that:`, ch:[`Detect changes in the internal environment`,`Carry out the response that corrects the deviation from the set point`,`Store information about past responses only`,`Have no functional role in the feedback loop`], ans:1, exp:`Effectors are the muscles, glands, or other organs that carry out the actual corrective action (such as sweat glands releasing sweat) directed by the control center in response to a detected deviation.` },
      { q:`Failure of homeostatic regulation, such as in uncontrolled diabetes, can result in:`, ch:[`No effect on the body`,`Perfectly stable internal conditions regardless of illness`,`Significant health problems due to internal conditions (like blood glucose) drifting far from their normal set point`,`Improved overall body function`], ans:2, exp:`When homeostatic mechanisms fail or are overwhelmed (as in uncontrolled diabetes, where blood glucose regulation breaks down), internal conditions can deviate significantly from their normal range, leading to serious health complications.` },
      { q:`Which of these is an example of a variable commonly regulated through homeostasis in the human body?`, ch:[`Eye color`,`Height`,`Number of fingers`,`Blood pH`], ans:3, exp:`Blood pH is tightly regulated within a very narrow range (about 7.35-7.45) through homeostatic mechanisms including buffering systems and respiratory/renal regulation, since even small deviations can be dangerous.` },
      { q:`If the body's internal temperature drops below its normal set point, an appropriate homeostatic (negative feedback) response would be to:`, ch:[`Trigger shivering and reduce blood flow to the skin to conserve heat`,`Stop all metabolic activity`,`Increase urine production only`,`Increase sweating and blood flow to the skin`], ans:0, exp:`When body temperature falls below the set point, negative feedback mechanisms trigger shivering (which generates heat through muscle activity) and constrict skin blood vessels to reduce heat loss, helping restore normal temperature.` },
    ]
  },
  {
    id:'bb133', cat:'Life Sciences', title:'Introduction to Enzymes & Catalysis', diff:'Easy',
    qs:[
      { q:`Enzymes are best described as:`, ch:[`Carbohydrates that store energy`,`Biological catalysts, usually proteins, that speed up chemical reactions`,`Structural components of the cell membrane only`,`Waste products of metabolism`], ans:1, exp:`Enzymes are typically proteins that act as biological catalysts, speeding up the rate of specific chemical reactions in cells without being consumed in the process.` },
      { q:`The specific region of an enzyme where the substrate binds and the reaction occurs is called the:`, ch:[`Substrate pocket only in some enzymes`,`Enzyme nucleus`,`Active site`,`Allosteric site`], ans:2, exp:`The active site is a specific region of the enzyme, often a pocket or groove, with a shape and chemical environment complementary to its substrate, where the catalyzed reaction takes place.` },
      { q:`Enzymes increase the rate of a chemical reaction primarily by:`, ch:[`Changing the overall energy released by the reaction`,`Making the reaction non-reversible`,`Increasing the amount of product formed beyond what is thermodynamically possible`,`Lowering the activation energy required for the reaction to proceed`], ans:3, exp:`Enzymes speed up reactions by lowering the activation energy barrier, allowing the reaction to proceed more quickly, without altering the reaction's overall energy change or final equilibrium.` },
      { q:`Enzyme specificity refers to the fact that:`, ch:[`Each enzyme generally binds to and acts on a specific substrate or a small group of related substrates`,`Enzymes cannot bind to any substrate`,`All enzymes are non-specific`,`A single enzyme can typically catalyze reactions for any substrate`], ans:0, exp:`Enzymes typically have active sites with shapes and chemical properties that fit only a specific substrate or a limited group of similar substrates, giving enzymes high specificity for their reactions.` },
      { q:`Which environmental factor, if raised too high, can denature most enzymes and drastically reduce their activity?`, ch:[`Slightly increased substrate concentration`,`Extreme temperature`,`Presence of water`,`Normal atmospheric pressure`], ans:1, exp:`Excessively high temperatures can disrupt the weak bonds maintaining an enzyme's three-dimensional shape, denaturing the protein and destroying the active site's ability to bind substrate, sharply reducing activity.` },
      { q:`Most human enzymes function optimally within which general pH range?`, ch:[`pH has no effect on enzyme activity`,`Extremely acidic (pH 1-2) in all cases`,`A relatively narrow range near neutral pH (though some, like pepsin, differ)`,`Extremely basic (pH 12-14) in all cases`], ans:2, exp:`Most human enzymes work best near neutral pH, though some specialized enzymes (like pepsin in the highly acidic stomach) have evolved to function optimally at very different pH levels suited to their environment.` },
      { q:`A cofactor is best described as:`, ch:[`The product of an enzymatic reaction`,`A type of substrate`,`A protein that always replaces the enzyme entirely`,`A non-protein helper molecule (often a metal ion) required by some enzymes for proper function`], ans:3, exp:`Cofactors are non-protein components, often metal ions (like zinc or magnesium) or organic molecules (coenzymes, often derived from vitamins), that many enzymes require to achieve full catalytic activity.` },
      { q:`A coenzyme is best described as:`, ch:[`An organic (often vitamin-derived) molecule that assists enzyme function`,`Part of the enzyme's active site made purely of amino acids`,`A type of inhibitor`,`An inorganic metal ion cofactor`], ans:0, exp:`Coenzymes are organic cofactor molecules, frequently derived from vitamins (such as NAD+ from niacin), that assist enzymes by transferring chemical groups or electrons during reactions.` },
      { q:`When an enzyme's shape is permanently altered such that it can no longer function properly, this is called:`, ch:[`Activation`,`Denaturation`,`Catalysis`,`Substrate binding`], ans:1, exp:`Denaturation occurs when an enzyme loses its proper three-dimensional structure (often due to heat or extreme pH), disrupting the active site and typically eliminating its catalytic function.` },
      { q:`An enzyme inhibitor is a molecule that:`, ch:[`Has no effect on enzyme function`,`Increases the rate of an enzymatic reaction`,`Decreases or blocks the activity of an enzyme`,`Is always identical to the natural substrate`], ans:2, exp:`Enzyme inhibitors are molecules that reduce or block enzyme activity, either by binding the active site (competitive) or another location on the enzyme (allosteric/noncompetitive), and are important in regulating metabolism and in many drugs.` },
      { q:`As substrate concentration increases (with a fixed amount of enzyme), the reaction rate will generally:`, ch:[`Immediately decrease to zero`,`Remain completely constant regardless of substrate level`,`Increase indefinitely without limit`,`Increase and then level off (plateau) once the enzyme becomes saturated with substrate`], ans:3, exp:`As substrate concentration rises, reaction rate increases until the enzyme's active sites become saturated; beyond that point, adding more substrate has little effect since all enzyme molecules are already working at capacity.` },
      { q:`Enzymes are typically reusable in reactions because they:`, ch:[`Are not consumed or permanently changed by the reaction they catalyze`,`Become part of the final product`,`Can only be used once per cell`,`Are permanently altered and destroyed after a single reaction`], ans:0, exp:`Enzymes function as catalysts, meaning they facilitate a reaction without being consumed or permanently altered, allowing a single enzyme molecule to catalyze the same reaction repeatedly.` },
    ]
  },
  {
    id:'bb134', cat:'Life Sciences', title:'Metabolism & Energy Balance Basics', diff:'Easy',
    qs:[
      { q:`Metabolism refers to:`, ch:[`Only the breakdown of food in the stomach`,`The sum of all chemical reactions occurring within an organism to maintain life`,`Only the production of waste products`,`The process of cell division exclusively`], ans:1, exp:`Metabolism encompasses all chemical reactions occurring within an organism, including both breaking down molecules for energy and building up molecules needed for growth and repair.` },
      { q:`Catabolism refers to metabolic reactions that:`, ch:[`Only occur in plants`,`Build larger molecules from smaller ones, requiring energy input`,`Break down larger molecules into smaller ones, typically releasing energy`,`Have no effect on molecular size`], ans:2, exp:`Catabolic reactions break down complex molecules (like carbohydrates and fats) into simpler ones, generally releasing energy that the cell can capture and use (often as ATP).` },
      { q:`Anabolism refers to metabolic reactions that:`, ch:[`Only occur during starvation`,`Are identical to catabolic reactions`,`Break down molecules and release energy`,`Build larger, more complex molecules from smaller ones, typically requiring energy input`], ans:3, exp:`Anabolic reactions construct larger, complex molecules (such as proteins from amino acids) from simpler building blocks, generally requiring an input of energy.` },
      { q:`Basal metabolic rate (BMR) refers to:`, ch:[`The minimum amount of energy the body needs to maintain basic life functions at rest`,`The total calories consumed in a meal`,`The rate at which muscles build new tissue`,`The rate of energy expenditure only during vigorous exercise`], ans:0, exp:`BMR is the amount of energy the body expends at complete rest to maintain essential functions like breathing, circulation, and cell repair, representing the majority of most people's daily energy expenditure.` },
      { q:`ATP (adenosine triphosphate) is often referred to as the cell's "energy currency" because it:`, ch:[`Cannot be broken down to release energy`,`Stores energy in its phosphate bonds and readily releases usable energy when hydrolyzed`,`Is a type of carbohydrate stored long-term`,`Only functions in plant cells`], ans:1, exp:`ATP stores energy in the bonds between its phosphate groups; when the terminal phosphate bond is hydrolyzed (ATP → ADP + phosphate), energy is released and can be used to power cellular processes.` },
      { q:`When caloric intake consistently exceeds caloric expenditure, the excess energy is generally:`, ch:[`Has no effect on body weight`,`Immediately eliminated with no storage`,`Stored primarily as fat (adipose tissue)`,`Converted directly into muscle without any fat storage`], ans:2, exp:`When more calories are consumed than expended, the body stores the excess energy primarily as fat in adipose tissue, which over time contributes to weight gain.` },
      { q:`Which macronutrient generally provides the most energy (calories) per gram?`, ch:[`All three provide identical energy per gram`,`Carbohydrates`,`Proteins`,`Fats`], ans:3, exp:`Fats provide approximately 9 calories per gram, more than double the roughly 4 calories per gram provided by carbohydrates or proteins, making fat the most energy-dense macronutrient.` },
      { q:`Aerobic cellular respiration, which uses oxygen to efficiently break down glucose for ATP production, occurs primarily within the:`, ch:[`Mitochondria`,`Golgi apparatus`,`Ribosomes`,`Nucleus`], ans:0, exp:`Mitochondria are the primary site of aerobic cellular respiration, where the majority of ATP is generated using oxygen through processes including the citric acid cycle and oxidative phosphorylation.` },
      { q:`During prolonged fasting or starvation, the body increasingly relies on breaking down which stored resource for energy, after glycogen stores are depleted?`, ch:[`Only dietary fiber`,`Fat stores (triglycerides)`,`Muscle exclusively, from the very first hour`,`Bone tissue`], ans:1, exp:`Once glycogen stores are depleted (typically within about a day of fasting), the body shifts to breaking down stored fat (triglycerides) for energy, and later increasingly draws on muscle protein if fasting continues further.` },
      { q:`Physical activity affects energy balance by:`, ch:[`Eliminating the need for food entirely`,`Having no impact on total energy expenditure`,`Increasing total energy expenditure, which can help offset caloric intake`,`Always decreasing metabolic rate`], ans:2, exp:`Physical activity increases the amount of energy the body expends beyond basal metabolic needs, which is an important component of overall energy balance alongside diet.` },
      { q:`A negative energy balance (expending more calories than consumed) generally results in:`, ch:[`No change in body weight`,`Immediate increase in muscle mass without fat loss`,`Weight gain`,`Weight loss, as the body draws on stored energy reserves`], ans:3, exp:`When energy expenditure exceeds caloric intake, the body must draw on stored energy reserves (primarily fat, and potentially some muscle) to meet its needs, generally resulting in weight loss over time.` },
      { q:`Glycogen serves as a short-term energy storage molecule primarily stored in which two tissues?`, ch:[`Liver and skeletal muscle`,`Lungs and kidneys`,`Brain and blood plasma`,`Bone and skin`], ans:0, exp:`Glycogen, a branched polymer of glucose, is stored mainly in the liver (which can release glucose into the blood for the whole body) and in skeletal muscle (which uses its glycogen locally for muscle activity).` },
    ]
  },
  {
    id:'bb135', cat:'Life Sciences', title:'Human Growth & Development', diff:'Easy',
    qs:[
      { q:`The stage of prenatal development from fertilization through about the second week, before major organ systems begin forming, is called the:`, ch:[`Fetal stage`,`Germinal/pre-embryonic stage`,`Neonatal stage`,`Adolescent stage`], ans:1, exp:`The germinal (pre-embryonic) stage covers roughly the first two weeks after fertilization, during which the zygote divides repeatedly and implants in the uterine wall, before the embryonic stage of organ formation begins.` },
      { q:`The embryonic stage of human prenatal development, during which most major organs and body structures begin to form, spans approximately:`, ch:[`Only the first 24 hours after fertilization`,`The entire pregnancy`,`Weeks 3 through 8`,`Months 6 through 9`], ans:2, exp:`The embryonic stage (roughly weeks 3-8) is a critical period of organogenesis, during which the foundations of all major organ systems are established, making the developing embryo especially vulnerable to teratogens during this time.` },
      { q:`From about week 9 until birth, the developing human is referred to as a:`, ch:[`Neonate`,`Zygote`,`Blastocyst`,`Fetus`], ans:3, exp:`Once major organ systems have been established by about week 9, the developing human is referred to as a fetus, and this stage is characterized primarily by growth and maturation of already-formed structures.` },
      { q:`Puberty is best described as the developmental period during which:`, ch:[`The body undergoes sexual maturation and develops secondary sexual characteristics`,`Bone growth stops entirely`,`Cognitive development ceases`,`An infant first learns to walk`], ans:0, exp:`Puberty is the stage of development, typically beginning in later childhood/early adolescence, during which hormonal changes trigger sexual maturation and the development of secondary sexual characteristics.` },
      { q:`Which hormone surge is primarily responsible for triggering the onset of puberty in both males and females?`, ch:[`Insulin`,`Gonadotropin-releasing hormone (GnRH), which stimulates the release of LH and FSH`,`Melatonin`,`Thyroid hormone alone`], ans:1, exp:`Increased secretion of GnRH from the hypothalamus stimulates the pituitary gland to release luteinizing hormone (LH) and follicle-stimulating hormone (FSH), which in turn trigger the hormonal cascade responsible for puberty.` },
      { q:`A "growth spurt" during adolescence refers to:`, ch:[`A stage occurring only in early infancy`,`A gradual, steady rate of growth throughout childhood`,`A relatively rapid increase in height and body growth, typically triggered by pubertal hormones`,`A period where growth completely stops`], ans:2, exp:`The adolescent growth spurt is a period of notably accelerated height and body growth, driven largely by rising levels of growth hormone and sex hormones during puberty.` },
      { q:`Growth plates (epiphyseal plates) in long bones are significant because they:`, ch:[`Store excess calcium only`,`Have no role in growth`,`Are responsible for producing red blood cells`,`Are regions of cartilage where bone lengthening occurs during childhood and adolescence`], ans:3, exp:`Growth plates are areas of active cartilage growth near the ends of long bones; as they gradually ossify (harden into bone) and eventually close after puberty, bone lengthening stops.` },
      { q:`Which of the following best describes senescence?`, ch:[`The biological process of aging, characterized by a gradual decline in physiological function over time`,`The process of puberty`,`Prenatal organ formation`,`The rapid growth phase of infancy`], ans:0, exp:`Senescence refers to the gradual biological aging process, marked by a progressive decline in cellular and physiological function that occurs over an organism's lifespan.` },
      { q:`Developmental milestones, such as walking or speaking first words, are generally used to:`, ch:[`Predict an individual's final adult height precisely`,`Assess whether a child's growth and development are progressing within a typical expected range`,`Diagnose adult diseases`,`Measure metabolic rate`], ans:1, exp:`Developmental milestones provide benchmarks (like typical ages for walking, talking, or specific motor skills) that help caregivers and clinicians assess whether a child's development is progressing typically.` },
      { q:`Menopause in females is best characterized by:`, ch:[`A stage occurring only in males`,`The onset of puberty`,`The permanent cessation of menstrual cycles and reproductive fertility, typically occurring in midlife`,`Increased fertility in later life`], ans:2, exp:`Menopause marks the natural, permanent end of menstrual cycles and fertility in women, typically occurring around ages 45-55, resulting from declining ovarian hormone production.` },
      { q:`Which factor is generally considered to have the greatest overall influence on an individual's growth and development, combining both hereditary and external influences?`, ch:[`Random chance with no identifiable factors`,`Genetics alone, with no environmental influence`,`Environmental factors alone, with no genetic influence`,`An interaction of genetic factors and environmental factors (such as nutrition and health care)`], ans:3, exp:`Growth and development result from a complex interaction between an individual's genetic potential and environmental factors such as nutrition, healthcare access, and living conditions.` },
      { q:`Adequate protein and calorie intake during childhood is especially important because deficiencies during this period can:`, ch:[`Impair physical growth and cognitive development, sometimes with lasting effects`,`Only affect adult bone density`,`Accelerate puberty onset`,`Have no lasting impact on development`], ans:0, exp:`Chronic nutritional deficiencies during critical childhood growth periods can impair both physical growth (such as stunting) and cognitive development, with effects that may persist even after nutrition later improves.` },
    ]
  },
  {
    id:'bb136', cat:'Life Sciences', title:'Chromosomal Disorders & Karyotypes', diff:'Medium',
    qs:[
      { q:`A karyotype is best described as:`, ch:[`A single gene's DNA sequence`,`A visual display of an individual's complete set of chromosomes, organized by size and shape`,`A type of protein found in cells`,`A measurement of blood pressure`], ans:1, exp:`A karyotype is an organized image or chart of all the chromosomes in a cell, arranged in pairs by size, shape, and banding pattern, allowing detection of chromosomal abnormalities in number or structure.` },
      { q:`How many total chromosomes does a typical human somatic (body) cell contain?`, ch:[`48`,`23`,`46`,`44`], ans:2, exp:`A typical human somatic cell contains 46 chromosomes, organized into 23 pairs (22 pairs of autosomes plus 1 pair of sex chromosomes).` },
      { q:`Down syndrome is most commonly caused by:`, ch:[`A missing X chromosome`,`A translocation between the X and Y chromosomes`,`A deletion of chromosome 21`,`An extra copy of chromosome 21 (trisomy 21)`], ans:3, exp:`Down syndrome most commonly results from trisomy 21 — the presence of three copies of chromosome 21 instead of the usual two — typically due to nondisjunction during meiosis.` },
      { q:`Nondisjunction refers to:`, ch:[`The failure of homologous chromosomes or sister chromatids to separate properly during cell division`,`A type of point mutation`,`The process of DNA replication`,`Normal separation of homologous chromosomes during meiosis`], ans:0, exp:`Nondisjunction is an error in meiosis (or mitosis) in which chromosomes fail to separate properly, resulting in gametes (or cells) with an abnormal number of chromosomes.` },
      { q:`Turner syndrome results from which chromosomal abnormality?`, ch:[`An extra Y chromosome in males (XYY)`,`A single X chromosome in females (45,X), missing the second sex chromosome`,`Trisomy of chromosome 21`,`An extra copy of chromosome 18`], ans:1, exp:`Turner syndrome occurs in females who have only one X chromosome (45,X) instead of the usual two, resulting in characteristic developmental features and infertility in most cases.` },
      { q:`Klinefelter syndrome is characterized by which chromosomal pattern?`, ch:[`47,XYY`,`45,X`,`47,XXY (an extra X chromosome in males)`,`Trisomy 21`], ans:2, exp:`Klinefelter syndrome occurs in males who inherit an extra X chromosome (47,XXY), which can affect physical development and often results in reduced fertility.` },
      { q:`A translocation, a type of chromosomal mutation, occurs when:`, ch:[`A single nucleotide is substituted`,`A chromosome is entirely destroyed with no trace remaining`,`A chromosome segment is duplicated in place`,`A segment of one chromosome breaks off and attaches to a different, non-homologous chromosome`], ans:3, exp:`In a translocation, a piece of one chromosome breaks off and becomes attached to a different, non-homologous chromosome, which can disrupt genes at the breakpoints or, in balanced cases, cause no direct harm but risk unbalanced gametes in offspring.` },
      { q:`Which of the following chromosomal disorders is generally associated with advanced maternal age increasing the risk of occurrence?`, ch:[`Trisomy 21 (Down syndrome), due to increased nondisjunction risk with maternal age`,`All chromosomal disorders occur with equal frequency regardless of maternal age`,`Point mutations exclusively`,`Only Y-linked disorders`], ans:0, exp:`The risk of nondisjunction events, and thus conditions like trisomy 21, increases notably with advanced maternal age, likely related to the prolonged arrest of oocytes in meiosis before ovulation.` },
      { q:`Amniocentesis and chorionic villus sampling are prenatal procedures primarily used to:`, ch:[`Treat chromosomal disorders directly`,`Obtain fetal cells for karyotyping and genetic testing to detect chromosomal abnormalities`,`Induce labor`,`Measure fetal heart rate only`], ans:1, exp:`Both procedures collect fetal cells (from amniotic fluid or placental tissue) that can be karyotyped or genetically tested to detect chromosomal abnormalities such as trisomies, prior to birth.` },
      { q:`A deletion mutation at the chromosomal level involves:`, ch:[`Exchange of segments between two chromosomes`,`Duplication of a chromosome segment`,`Loss of a segment of a chromosome, along with any genes located there`,`Reversal of a chromosome segment's orientation`], ans:2, exp:`A chromosomal deletion occurs when a segment of a chromosome (and the genes it contains) is lost, which can range from minor to severe in effect depending on the size and location of the deleted region.` },
      { q:`Most autosomal trisomies (other than trisomy 21, 18, and 13) are strongly associated with:`, ch:[`Guaranteed survival to adulthood with no complications`,`Increased fertility`,`No significant health effects in most cases`,`Very high rates of miscarriage, as most are incompatible with survival to birth`], ans:3, exp:`Most autosomal trisomies involve enough extra genetic material to be lethal early in development, so the vast majority end in miscarriage; trisomy 21, 18, and 13 are among the few capable of resulting in live birth, though 18 and 13 carry very high infant mortality.` },
      { q:`An inversion mutation at the chromosomal level occurs when:`, ch:[`A chromosome segment breaks off, flips, and reattaches in reverse orientation`,`Two entirely different chromosomes exchange segments`,`A whole extra chromosome is gained`,`A chromosome segment is duplicated`], ans:0, exp:`An inversion occurs when a chromosome segment breaks off, reverses in orientation, and reattaches; this can disrupt genes at the breakpoints and, in some cases, interfere with normal pairing and crossing over during meiosis.` },
    ]
  },
  {
    id:'bb137', cat:'Life Sciences', title:'Symbiosis & Species Interactions', diff:'Easy',
    qs:[
      { q:`Symbiosis is broadly defined as:`, ch:[`Competition between two species for the same limited resource`,`A close, long-term biological interaction between two different species`,`The predation of one species by another`,`The extinction of a species`], ans:1, exp:`Symbiosis refers to any close, sustained ecological relationship between two different species living in direct contact, which can be beneficial, harmful, or neutral to each participant.` },
      { q:`In a mutualistic relationship, the interaction between the two species results in:`, ch:[`One species benefiting while the other is unaffected`,`Both species being harmed`,`Both species benefiting`,`One species benefiting while the other is harmed`], ans:2, exp:`Mutualism describes a symbiotic relationship in which both participating species gain a net benefit, such as bees receiving nectar while pollinating flowers.` },
      { q:`The relationship between a tapeworm and its host, in which the tapeworm benefits at the host's expense, is an example of:`, ch:[`Competition`,`Mutualism`,`Commensalism`,`Parasitism`], ans:3, exp:`Parasitism is a symbiotic relationship in which one organism (the parasite) benefits at the direct expense of the other (the host), often causing harm without immediately killing it.` },
      { q:`Commensalism describes a relationship in which:`, ch:[`One species benefits while the other is neither helped nor harmed`,`Both species are harmed`,`One species is completely dependent on eating the other`,`Both species benefit equally`], ans:0, exp:`In commensalism, one species derives a benefit from the interaction while the other species experiences no significant positive or negative effect, such as barnacles attaching to a whale for transport.` },
      { q:`Predation is best described as an interaction in which:`, ch:[`Two species compete for the same resource without direct contact`,`One organism (the predator) kills and consumes another organism (the prey)`,`Both organisms benefit from close contact`,`One organism lives on or in another without killing it`], ans:1, exp:`Predation involves one organism (the predator) capturing, killing, and consuming another organism (the prey) as a food source, directly affecting the population dynamics of both species.` },
      { q:`Interspecific competition occurs when:`, ch:[`One species is completely unaffected by another's presence`,`Members of the same species compete for resources`,`Members of two different species compete for the same limited resource, potentially reducing the fitness of both`,`Two species cooperate to share resources equally`], ans:2, exp:`Interspecific competition occurs between individuals of different species vying for the same limited resource (such as food, water, or space), which can reduce the survival or reproduction of both competing species.` },
      { q:`The competitive exclusion principle states that:`, ch:[`Competition only occurs between members of the same species`,`All species always cooperate rather than compete`,`Two species can indefinitely coexist while competing for the exact same limiting resource`,`Two species competing for the exact same limiting niche cannot coexist indefinitely; one will eventually outcompete the other`], ans:3, exp:`The competitive exclusion principle holds that when two species compete for an identical limiting resource/niche, one species will typically be more efficient and eventually outcompete and displace the other over time.` },
      { q:`Mycorrhizae, a mutualistic association between fungi and plant roots, benefits the plant primarily by:`, ch:[`Increasing the plant's ability to absorb water and minerals from the soil`,`Preventing the plant from photosynthesizing`,`Directly replacing the plant's roots`,`Producing toxins that harm the plant`], ans:0, exp:`Mycorrhizal fungi form associations with plant roots, greatly extending the effective surface area for water and nutrient (especially phosphorus) absorption, while the fungus receives sugars produced by the plant.` },
      { q:`Cleaner fish that eat parasites off larger fish, benefiting both species, represent an example of:`, ch:[`Parasitism`,`Mutualism`,`Predation`,`Commensalism only`], ans:1, exp:`This relationship benefits both organisms — the cleaner fish gains a food source (parasites), while the larger fish is relieved of harmful parasites — making it a clear example of mutualism.` },
      { q:`Resource partitioning is an evolutionary outcome that can help reduce competition between species by:`, ch:[`Increasing direct predation between the species`,`Eliminating one species entirely`,`Allowing species to divide a limited resource by using different parts of it, or using it at different times`,`Forcing both species to use identical resources at identical times`], ans:2, exp:`Resource partitioning allows similar species to coexist by evolving to use different portions of a shared resource, or use it at different times/locations, reducing the intensity of direct competition between them.` },
      { q:`Clownfish living safely among the stinging tentacles of sea anemones, gaining protection from predators while providing the anemone with food scraps and nutrients, best illustrates:`, ch:[`Predation`,`Interspecific competition`,`Parasitism`,`Mutualism`], ans:3, exp:`Both organisms benefit in this relationship — the clownfish gains protection from predators (being immune to the anemone's sting), while the anemone benefits from food scraps, waste nutrients, and improved water circulation — a clear example of mutualism.` },
      { q:`Intraspecific competition differs from interspecific competition in that intraspecific competition occurs:`, ch:[`Between members of the same species competing for the same limited resources`,`Only between predator and prey`,`Only in mutualistic relationships`,`Between members of two different species`], ans:0, exp:`Intraspecific competition occurs among individuals of the same species, who typically have nearly identical resource needs and therefore often compete even more intensely than individuals of different species (interspecific competition).` },
    ]
  },
  {
    id:'bb138', cat:'Life Sciences', title:'Animal Behavior Basics', diff:'Easy',
    qs:[
      { q:`Innate behaviors are best described as behaviors that are:`, ch:[`Learned entirely through experience`,`Genetically programmed and present without needing to be learned`,`Only found in humans`,`Random and unpredictable`], ans:1, exp:`Innate (instinctive) behaviors are largely determined by genetics and typically appear in full form without prior learning or experience, such as a spider's web-building ability.` },
      { q:`Learned behaviors differ from innate behaviors in that learned behaviors:`, ch:[`Are identical across all species`,`Are present from birth in fixed form`,`Develop or change as a result of experience`,`Cannot be modified over an organism's lifetime`], ans:2, exp:`Learned behaviors are shaped and modified by an individual's experiences and environment over time, unlike innate behaviors, which are largely fixed and genetically determined.` },
      { q:`Imprinting, famously studied by Konrad Lorenz in geese, is an example of a behavior that:`, ch:[`Never involves any learning component`,`Only occurs in adult animals`,`Can be learned at any point in an animal's life with equal ease`,`Occurs rapidly during a specific early critical period and is highly resistant to change afterward`], ans:3, exp:`Imprinting is a rapid form of learning that occurs during a specific, brief critical period early in life (such as goslings imprinting on the first moving object they see), and the resulting behavior is typically very resistant to change afterward.` },
      { q:`Habituation refers to the process by which an animal:`, ch:[`Decreases or stops responding to a repeated stimulus that has no significant consequence`,`Learns a completely new skill through trial and error`,`Only occurs in response to dangerous stimuli`,`Increases its response to a repeated, harmless stimulus over time`], ans:0, exp:`Habituation is a simple form of learning in which an animal gradually reduces its response to a repeated stimulus that proves to be harmless or insignificant, allowing it to conserve energy and attention for more important stimuli.` },
      { q:`A fixed action pattern is best described as:`, ch:[`A highly variable behavior that changes each time it's performed`,`A stereotyped, largely unchangeable sequence of behavior triggered by a specific stimulus`,`A behavior that must be taught by a parent`,`A behavior found only in domesticated animals`], ans:1, exp:`Fixed action patterns are innate, stereotyped behavior sequences that, once triggered by a specific stimulus (a "releaser"), run to completion in essentially the same way every time, regardless of whether the stimulus was appropriate.` },
      { q:`Classical conditioning, as demonstrated by Pavlov's experiments with dogs, involves:`, ch:[`Instinctive behavior with no learning involved`,`Learning purely by observing another animal`,`Learning to associate a previously neutral stimulus with a stimulus that naturally triggers a response`,`Punishing an unwanted behavior to eliminate it`], ans:2, exp:`In classical conditioning, an animal learns to associate a neutral stimulus (like a bell) with another stimulus that naturally produces a response (like food triggering salivation), eventually causing the neutral stimulus alone to elicit the response.` },
      { q:`Operant conditioning differs from classical conditioning in that operant conditioning involves:`, ch:[`No behavioral change whatsoever`,`Only occurring in a laboratory setting`,`Associating two stimuli together passively`,`An animal learning to associate its own behavior with a consequence (reward or punishment)`], ans:3, exp:`Operant conditioning involves an animal learning to associate a voluntary behavior with its consequences — behaviors followed by rewards tend to increase, while those followed by punishment tend to decrease.` },
      { q:`Migratory behavior in many animal species, such as birds flying south for winter, is best understood as:`, ch:[`An adaptation that allows animals to seek more favorable conditions (food, climate) at different times of year`,`A random, non-repeating movement pattern`,`A behavior found only in mammals`,`A behavior with no adaptive value`], ans:0, exp:`Migration is an adaptive behavior allowing animals to move to more favorable environments (with better food availability, climate, or breeding conditions) as seasons change, improving survival and reproductive success.` },
      { q:`Communication through pheromones (chemical signals) is commonly used by many insect species to:`, ch:[`Prevent all social interaction`,`Convey information such as alarm signals, trail marking, or mate attraction`,`Only regulate body temperature`,`Replace the need for any other sensory systems`], ans:1, exp:`Pheromones are chemical signals released by many insects (and other animals) that convey specific information to other members of their species, such as marking food trails, signaling alarm, or attracting mates.` },
      { q:`Social behaviors such as cooperative hunting in wolf packs primarily provide which advantage?`, ch:[`Elimination of the need to hunt at all`,`Decreased chance of successfully catching prey`,`Increased likelihood of successfully capturing larger or more difficult prey compared to hunting alone`,`No change in hunting success`], ans:2, exp:`Cooperative hunting allows group members to work together to take down prey that would be difficult or impossible for a single individual to catch alone, increasing overall hunting success and food acquisition.` },
      { q:`A courtship display, such as a peacock spreading its elaborate tail feathers, primarily functions to:`, ch:[`Regulate body temperature`,`Establish territory boundaries exclusively`,`Scare away potential predators only`,`Attract a mate and signal genetic fitness to potential partners`], ans:3, exp:`Courtship displays like the peacock's tail have evolved largely through sexual selection, signaling health, vigor, and genetic quality to potential mates, increasing the displaying individual's chances of successfully reproducing.` },
      { q:`Circadian rhythms refer to behavioral and physiological cycles that repeat approximately every:`, ch:[`24 hours`,`Week`,`Year`,`Hour`], ans:0, exp:`Circadian rhythms are internally generated biological cycles lasting approximately 24 hours, influencing behaviors such as sleep-wake patterns, body temperature fluctuations, and hormone release, and are typically synchronized by light exposure.` },
    ]
  },
  {
    id:'bb139', cat:'Life Sciences', title:'Comparative Anatomy', diff:'Medium',
    qs:[
      { q:`Comparative anatomy is the scientific study of:`, ch:[`The behavior of different animal species`,`Similarities and differences in the body structures of different organisms`,`The chemical composition of cells only`,`Population sizes across ecosystems`], ans:1, exp:`Comparative anatomy examines and compares the anatomical structures of different species to understand evolutionary relationships, functional adaptations, and shared ancestry.` },
      { q:`Homologous structures across species are primarily explained by:`, ch:[`Identical environmental pressures acting independently`,`Convergent evolution from unrelated ancestors`,`Descent from a common ancestor, with the structure modified over time for different functions`,`Coincidental similarity with no evolutionary connection`], ans:2, exp:`Homologous structures share an underlying anatomical pattern because they were inherited from a shared common ancestor, even though the structure may now serve different functions in different descendant species.` },
      { q:`Analogous structures, in contrast to homologous structures, arise from:`, ch:[`Random genetic drift with no functional advantage`,`A single shared developmental gene network`,`A shared common ancestor with an identical original structure`,`Independent evolutionary origins responding to similar environmental pressures (convergent evolution)`], ans:3, exp:`Analogous structures perform similar functions in different species due to convergent evolution — independent evolutionary solutions to similar environmental challenges — rather than because of shared ancestry for that particular structure.` },
      { q:`The forelimb bone arrangement (humerus, radius, ulna, and digits) shared by humans, cats, whales, and bats, despite differing external forms, is a classic example of:`, ch:[`Homologous structures`,`Vestigial structures only`,`Convergent structures with no shared ancestry`,`Analogous structures`], ans:0, exp:`Despite serving very different functions (grasping, running, swimming, flying), the underlying bone structure and arrangement of vertebrate forelimbs is remarkably consistent, reflecting descent from a common tetrapod ancestor.` },
      { q:`The wings of a butterfly and the wings of a bird are considered analogous structures because they:`, ch:[`Share an identical bone structure inherited from a common ancestor`,`Serve a similar function (flight) but evolved independently and have very different underlying structures`,`Are found only in reptiles`,`Have no functional similarity at all`], ans:1, exp:`Butterfly and bird wings both enable flight but evolved completely independently from very different ancestral structures (an insect exoskeleton versus a vertebrate forelimb), making them analogous rather than homologous.` },
      { q:`Comparative embryology, a branch related to comparative anatomy, provides evolutionary evidence by showing that:`, ch:[`Embryonic structures have no bearing on adult anatomy`,`Vertebrate embryos of different species look completely dissimilar from the earliest stages`,`Many vertebrate embryos share striking structural similarities early in development, such as pharyngeal slits`,`Only mammals show any embryonic development`], ans:2, exp:`Comparative embryology reveals that early-stage embryos of many vertebrate groups (fish, reptiles, birds, mammals) share notable structural similarities, such as pharyngeal slits, reflecting deeply conserved developmental genetic programs from a shared ancestor.` },
      { q:`Vestigial structures, studied within comparative anatomy, are structures that:`, ch:[`Are entirely absent in all species`,`Only appear in the fossil record, never in living organisms`,`Serve a critical, fully functional role in the current species`,`Have been reduced in size or function compared to a similar structure with a clear function in a related or ancestral species`], ans:3, exp:`Vestigial structures are reduced or non-functional remnants of structures that served a clear purpose in ancestral species, such as the pelvic bones found in some whales, remnants of their land-dwelling ancestors' hind limbs.` },
      { q:`The comparative study of skeletal structures across species is particularly useful for scientists because it can help:`, ch:[`Reveal evolutionary relationships and how structures have been modified for different functions over time`,`Measure an organism's current body temperature`,`Replace the need for genetic (DNA) evidence entirely`,`Determine the exact date an organism was born`], ans:0, exp:`By comparing skeletal (and other anatomical) structures across species, scientists can infer evolutionary relationships and understand how a shared ancestral structure has been modified through natural selection to serve different functions in different lineages.` },
      { q:`Which of these pairs represents an example of homologous structures?`, ch:[`Human arm and octopus tentacle`,`Human arm and bat wing`,`Butterfly wing and bird wing`,`Shark fin and dolphin fin`], ans:1, exp:`The human arm and bat wing share the same underlying bone structure (humerus, radius, ulna, and digit bones) inherited from a common tetrapod ancestor, making them homologous despite their very different current functions.` },
      { q:`Shark fins (fish) and dolphin fins (mammals) are considered analogous rather than homologous because they:`, ch:[`Have no function at all`,`Share an identical internal bone structure inherited from a shared recent ancestor`,`Serve a similar swimming function but evolved independently from different ancestral structures`,`Are found in organisms with no evolutionary relationship whatsoever`], ans:2, exp:`Although both fins support swimming, sharks (fish) and dolphins (mammals) evolved their fin structures independently and from different ancestral starting points, making the fins analogous structures resulting from convergent evolution rather than shared ancestry of the fin itself.` },
      { q:`Studying the number and arrangement of teeth (dentition) across different mammal species can help scientists infer:`, ch:[`Only an individual's exact age at death`,`The species' geographic range exclusively`,`Nothing useful about a species' diet or evolutionary relationships`,`Likely diet type (carnivore, herbivore, omnivore) and evolutionary relatedness to other species`], ans:3, exp:`Comparative anatomy of teeth shape and arrangement can reveal a great deal about an animal's diet (e.g., sharp carnassial teeth in carnivores vs. flat grinding molars in herbivores) as well as evolutionary relationships among species.` },
      { q:`The general body plan similarities among all vertebrates (a segmented backbone, dorsal nerve cord, and paired appendages) are best explained by:`, ch:[`Inheritance of a conserved basic body plan from a shared common vertebrate ancestor`,`Random chance with no evolutionary explanation`,`Direct communication between different vertebrate species`,`Coincidental convergent evolution occurring independently in every vertebrate lineage`], ans:0, exp:`The shared basic body plan across vertebrates strongly reflects descent from a common ancestor that already possessed these fundamental features, which have since been modified in different lineages while retaining the same underlying blueprint.` },
    ]
  },
  {
    id:'bb140', cat:'Life Sciences', title:'Biotechnology Basics: Cloning & GMOs', diff:'Medium',
    qs:[
      { q:`Cloning, in a biological context, refers to:`, ch:[`Creating an organism that is genetically distinct from its parent`,`Producing a genetically identical copy of an organism, cell, or piece of DNA`,`Randomly mutating an organism's genome`,`Combining the DNA of two unrelated species only`], ans:1, exp:`Cloning involves creating a genetically identical copy of a DNA sequence, cell, or entire organism, without the genetic recombination that typically occurs during sexual reproduction.` },
      { q:`Dolly the sheep, born in 1996, was significant as the first mammal cloned from:`, ch:[`A sperm cell alone`,`An embryonic cell`,`An adult somatic (body) cell, using a technique called somatic cell nuclear transfer`,`A random combination of two different species' DNA`], ans:2, exp:`Dolly was created using somatic cell nuclear transfer, in which the nucleus from an adult mammary gland cell was transferred into an egg cell whose own nucleus had been removed, demonstrating that a differentiated adult cell's genome could direct development of a whole new organism.` },
      { q:`A genetically modified organism (GMO) is an organism whose:`, ch:[`Physical appearance has changed due to aging`,`Diet has simply been changed`,`Behavior has been altered through training`,`Genetic material has been altered using biotechnology, often by introducing genes from another organism`], ans:3, exp:`GMOs have had their genetic material intentionally altered using biotechnology techniques, frequently by inserting a gene from a different species to introduce a desired trait, such as pest resistance in crops.` },
      { q:`A common example of a genetically modified crop is one engineered to:`, ch:[`Resist certain pests or herbicides, improving crop yield`,`Only grow in a laboratory setting`,`Be completely unable to reproduce`,`Have no genetic material at all`], ans:0, exp:`Many GMO crops are engineered to express traits such as resistance to specific insect pests (e.g., Bt corn) or tolerance to certain herbicides, which can improve agricultural yield and reduce pesticide use.` },
      { q:`Recombinant DNA technology fundamentally involves:`, ch:[`Reproducing an organism sexually`,`Combining DNA fragments from different sources (often different organisms) into a single DNA molecule`,`Destroying all DNA within a cell`,`Only sequencing DNA without modification`], ans:1, exp:`Recombinant DNA technology involves combining DNA from different sources — often using restriction enzymes to cut DNA and ligase to join fragments — into a new, hybrid DNA molecule.` },
      { q:`Restriction enzymes are useful tools in biotechnology because they:`, ch:[`Prevent any genetic modification from occurring`,`Randomly destroy all DNA in a sample`,`Cut DNA at specific recognition sequences, allowing precise manipulation of DNA fragments`,`Only function in animal cells`], ans:2, exp:`Restriction enzymes recognize and cut DNA at specific short sequences, allowing scientists to precisely excise genes of interest or cut plasmid vectors for inserting new genetic material.` },
      { q:`Reproductive cloning, which aims to create an entire new organism, differs from therapeutic cloning, which aims primarily to:`, ch:[`Permanently alter an organism's behavior`,`Eliminate the need for any cloning technology`,`Create a fully independent new organism for reproduction`,`Produce cells or tissues (such as stem cells) for potential medical treatment, without creating a full new organism`], ans:3, exp:`Therapeutic cloning focuses on generating specific cells or tissues (such as patient-matched stem cells) for potential medical use, stopping short of developing a full new organism, unlike reproductive cloning.` },
      { q:`One potential benefit commonly cited for genetically modified crops is that they can:`, ch:[`Potentially increase yields, improve nutritional content, or reduce the need for certain pesticides`,`Only be grown in outer space`,`Eliminate the need for water or sunlight`,`Guarantee complete elimination of all agricultural risk`], ans:0, exp:`Proponents point to potential benefits of GMOs such as increased crop yields, enhanced nutritional profiles (e.g., Golden Rice with added vitamin A), and reduced reliance on certain chemical pesticides.` },
      { q:`Common concerns raised about GMOs include questions about:`, ch:[`Whether GMOs have any measurable effect on agriculture at all`,`Potential ecological effects, gene flow to wild relatives, and the need for ongoing safety and environmental monitoring`,`Only concerns about GMO taste`,`GMOs being impossible to regulate in any way`], ans:1, exp:`Common concerns about GMOs include potential ecological impacts (such as gene flow to wild or non-GMO plant relatives), effects on non-target organisms, and the importance of ongoing research and regulation to monitor safety.` },
      { q:`A transgenic organism is one that:`, ch:[`Can only reproduce asexually`,`Has had all of its genetic material removed`,`Has had genetic material from a different species deliberately inserted into its genome`,`Has never been genetically altered in any way`], ans:2, exp:`A transgenic organism carries genetic material (typically one or more specific genes) that has been deliberately transferred from a different species into its genome using biotechnology techniques.` },
      { q:`Genetic engineering techniques are used in medicine to produce which of the following?`, ch:[`Naturally occurring antibodies without any lab involvement`,`Only vaccines with no other medical applications`,`Only decorative plant varieties`,`Recombinant proteins such as human insulin, produced by genetically engineered bacteria`], ans:3, exp:`Genetic engineering enabled the production of recombinant human insulin by inserting the human insulin gene into bacteria, allowing bacteria to mass-produce a safe, effective insulin supply instead of relying on animal-derived insulin.` },
      { q:`A plasmid vector used in genetic engineering functions primarily as:`, ch:[`A carrier molecule that transports a gene of interest into a host cell, such as bacteria`,`A type of restriction enzyme`,`A structure found only in animal cells`,`A tool to permanently destroy target DNA`], ans:0, exp:`Plasmids are small circular DNA molecules commonly used as vectors in genetic engineering; a gene of interest is inserted into the plasmid, which is then introduced into a host cell (often bacteria) so it can be replicated and expressed.` },
    ]
  },
];
